"""Original catalogue records. Full external publications are reference-only evidence."""
import json, pathlib, hashlib

ROOT = pathlib.Path(__file__).parent
rows = []
def add(i, statement, inp, status, proof, lives):
    rows.append(dict(id=i, statement=statement, input=inp, status=status,
                     where_the_proof_is=proof, where_it_lives=lives))

A = 'Alpöge (adopted input A): RH and GRH for primitive Dirichlet L-functions; no independent verification of the unseen Lean import tree is claimed.'
M = 'Masullo (conditional input M): GRH for unitary Hecke L-functions over all number fields.'
geo = 'GRH_NIGHT/number_theory; finite étale/arithmetic Frobenius dictionary, SGA 1, Exposé V, §7; comparison with the trace programme in inherited RETURN_ZETA_TWO, IA01/IA06. No archive scan newly certified in this row.'
specz = 'GRH_NIGHT/number_theory; closed points and Euler product of Spec Z, Weil explicit-formula side of the inherited cote-1 trace programme. No assertion that finite-field purity proves this number-field estimate.'
pic = 'GRH_NIGHT/number_theory; Pic(Spec O_K), finite étale class-field covers, SGA 1, Exposé V, §7; RETURN_ZETA_TWO IA02; SA06 B.4a–e and REVLOC I.5/I.8b where applicable.'
zero = 'GRH_NIGHT/number_theory; zero divisor of an arithmetic L-function and explicit formula. Grothendieck finite-field monodromy is a comparison framework, not an additional proved number-field implication.'
classical = 'classical with an exact locator; RH/Dirichlet-GRH hypothesis discharged by adopted A'
conditional = 'conditional on M; classical with an exact locator'

add('NT-P01', 'For x≥59, |ψ(x)−x|<√x(log x)^2/(8π), where ψ(x)=Σ_{p^m≤x}log p.', A, classical, 'Schoenfeld (1976), Theorem10 equation(6.2), printed337 gives x≥73.2; improved x≥59 from Johnston(2022) Theorem3.2 equation(3.3), with A satisfying every finite-height requirement. See S-NT-SCHOENFELD and S-NT-JOHNSTON.', specz)
add('NT-P02', 'For x≥599, |θ(x)−x|<√x(log x)^2/(8π), θ(x)=Σ_{p≤x}log p. For x≥23·10^8 the stronger factor (log x−2)log x bounds both θ and ψ.', A, classical, 'Schoenfeld (1976), Theorem 10, equations (6.1),(6.3), printed p.337.', specz)
add('NT-P03', 'For x≥2657, |π(x)−li(x)|<√x log x/(8π); li is the usual logarithmic integral, not the integral normalized to vanish at 2.', A, classical, 'Schoenfeld(1976), Corollary1, equation(6.18), printed339. Directly checked independent primary proof: Johnston(2022), Theorem3.2 equation(3.6), with A satisfying the finite-height condition; §2 explicitly includes ordinary unnormalised counting functions. Original Schoenfeld page image not newly inspected.', specz)
add('NT-P04', 'For every x≥2 and c=1/2+2/log x, (x−c√x log x,x+c√x log x) contains a prime; enlarging the coefficient to c+1 gives at least √x primes. In particular consecutive prime gaps are O(√p log p).', A, classical, 'Dudek–Grenié–Molteni (2016), Theorem 1.1, author PDF p.1.', specz)
add('NT-P05', 'There are absolute positive constants x0,c1,c2 such that, for (a,q)=1, x≥x0 and c1 φ(q)√x log x≤h≤x, π(x+h;q,a)−π(x;q,a)≥c2 h/(φ(q)log x). If h/(φ(q)√x log x)→∞, the corresponding asymptotic holds.', A+' Only the Dirichlet functions modulo q are required.', classical, 'Grenié–Molteni–Perelli (2016), Theorem 1 and the immediately following asymptotic statement, author PDF p.2.', geo+' Cyclotomic cover Spec Z[ζ_q,1/q]→Spec Z[1/q].')
add('NT-P06', 'If q>3 and (a,q)=1, the least prime p≡a mod q is at most (φ(q)log q)^2.', A, 'carried background IA02, with source and threshold rechecked under A', 'Lamzouri–Li–Soundararajan, corrected arXiv:1309.3595v3, Corollary 1.2, author p.3.', geo+' RETURN_ZETA_TWO IA02; cyclotomic Frobenius coset.')
add('NT-P07', 'For a prime q≥5, the least quadratic nonresidue modulo q is <(log q)^2.', A+' GRH for the quadratic character suffices for this specialization.', 'carried background IA02, with corrected source rechecked under A', 'Lamzouri–Li–Soundararajan v3, Corollary 1.1, author p.2.', geo+' RETURN_CX_GRH CX-N02; Kummer quadratic-character detector.')
add('NT-P08', 'For q≥3000 and a proper subgroup H<(Z/qZ)^×, the least prime ℓ∤q with ℓ mod q outside H is ≤(log q+B(q))^2, where A(q)=max(0,2loglog q−8/5−Σ_{p|q}log p/(p−1)) and B(q)=max(0,2loglog q+3+2ω(q)(loglog q)^2/log q−2A(q)).', A, classical, 'Lamzouri–Li–Soundararajan v3, Theorem 1.1(1), author p.2. Constants read in primary text.', geo+' RETURN_CX_GRH CX-N02 and subgroup/finite Kummer tests.')
add('NT-P09', 'For a prime p and r=ω(p−1), the least primitive root is O(r^4(log r+1)^4(log p)^2), hence O((log p)^6). The implied constant is not given numerically here.', A+' This is the least primitive root for a fixed modulus, distinct from prescribing an integer and varying the prime.', classical, 'Shoup (1992), Searching for primitive roots in finite fields, Theorem 3, author PDF p.4; source page image inspected. The O(log^6 p) simplification is proved in section.tex.', geo+' RETURN_CX_GRH CX-N05 is a different extension-field construction; finite-field G_m points and Kummer character sieve.')
add('NT-P10', 'There is no exceptional real zero β with 1/2<β<1 for any primitive real Dirichlet L-function. This removes the exceptional-zero alternative in results whose sole extra hypothesis was that exclusion.', A, 'immediate proved consequence of the exact zero-location input', 'Definition of A and the nonvanishing statement ALPOGE_Main.lean LFunction_ne_zero_of_half_lt_re; not a claim of new formal checking.', pic+' RETURN_ZETA_TWO IA05: use the previously proved Stark descent where the result concerns CM fields.')

add('NT-C01', 'Let L/K be finite Galois, G its group, C one conjugacy class, n_L=[L:Q], Δ_L=|disc L|. For x≥1, |ψ_C(x)−(|C|/|G|)x|≤(|C|/|G|)E_L(x), where E_L(x)=√x[(log x/(2π)+2)log Δ_L+(log²x/(8π)+2)n_L] and ψ_C sums unramified prime powers with Frobenius power in C, weighted log Np.', M+' RH ζ_L alone is sufficient; A suffices if L/Q is abelian.', conditional, 'Grenié–Molteni (2019), Theorem 1.1, author PDF p.2; image inspected. Unramified version explicitly included.', geo+' RETURN_ZETA_TWO IAQ039/IAQ040–071; SA07 D.3.2 and E.2/E.3.')
add('NT-C02', 'With the notation of NT-C01 and x≥2, |π_C(x)−δ_C Li_2(x)|≤δ_C B_L(x), δ_C=|C|/|G|, Li_2(x)=∫_2^xdt/log t and B_L(x)=√x[(1/(2π)+3/log x)log Δ_L+(log x/(8π)+1/(4π)+6/log x)n_L]. π_C counts unramified primes without log weights.', M+' RH ζ_L suffices; A suffices for L/Q abelian.', conditional, 'Grenié–Molteni (2019), Corollary 1.2, author PDF p.3; image inspected. The notation π is fixed here to avoid a typographical log-weight in the source introduction.', geo)
add('NT-C03', 'For L/K finite Galois, L≠Q, every conjugacy class contains the Frobenius of an unramified prime ideal p of K of residue degree one over Q and Np≤(4log Δ_L+2.5[L:Q]+5)^2. This statement does not itself permit excluding an arbitrary additional finite set of primes.', M+' Precisely RH ζ_L and RH ζ_Q as stated in Bach–Sorenson §2; A supplies ζ_Q and also ζ_L if L/Q abelian.', conditional, 'Bach–Sorenson (1996), Theorem 5.1, printed p.1729/PDF p.13; hypotheses §2 p.1720 and Corollary 3.3 p.1721. Primary PDF independently opened; geometry agent checked source.', geo+' RETURN_CX_GRH CX-N11 auxiliary-field prime; see NT-F04 for an explicit finite-exclusion criterion.')
add('NT-C04', 'For a number field K, prime ideals occur with π_K(x+h)−π_K(x)≫h/log x once h≥c1√x(n_K log x+log Δ_K), x≥x0 and h≤x; the implied lower-bound constant and x0,c1 are absolute. The asymptotic holds if h/[√x(n_K log x+log Δ_K)]→∞.', M+' Only RH ζ_K is needed; A suffices if K/Q is abelian.', conditional, 'Grenié–Molteni–Perelli (2016), Theorem 2 and following sentence, author PDF p.2.', specz+' Replace Spec Z by Spec O_K; closed-point norms.')
add('NT-C05', 'Under GRH for the unramified ideal-class Hecke characters of K, Cl(K) is generated by prime ideals of norm at most 12(log Δ_K)^2. A alone does not supply this for arbitrary K, even when K/Q is abelian.', M+' Finite-order Hecke characters of the ideal class group, equivalently sufficient RH input from the Hilbert class field.', 'carried background, conditional on M; primary fresh retrieval not completed', 'Bach (1990), Theorem 4, printed p.375 and corollary p.376, as precisely carried in RETURN_CX_GRH CX-N07. The AMS endpoint was inaccessible in this run; do not claim fresh page inspection.', pic+' RETURN_CX_GRH CX-N07; algorithmic treatment owned by complexity agent.')

add('NT-H01', 'For a primitive Dirichlet character of conductor q≥10^10, 1/V(q)≤|L(1,χ)|≤U(q), U=2e^γ(loglog q−log2+1/2+1/loglog q), V=(12e^γ/π²)(loglog q−log2+1/2+1/loglog q+14loglog q/log q).', A, 'carried background IA02, corrected formula rechecked', 'Lamzouri–Li–Soundararajan v3, Theorem 1.5, author pp.3–4; corrected v3 used throughout.', pic+' RETURN_ZETA_TWO IA02. The lower bound is inverse-loglog, not loglog.')
add('NT-H02', 'For a negative fundamental discriminant −q with q≥10^10, √q/[πV(q)]≤h(−q)≤√q U(q)/π, with U,V from NT-H01.', A, 'carried background IA02, exact threshold and normalization rechecked', 'Lamzouri–Li–Soundararajan v3, Corollary 1.3 and equation (1.3), author p.4.', pic+' SA06 quadratic-order specialization requires maximal order/fundamental discriminant; no nonmaximal-order claim without conductor factors.')
add('NT-H03', 'For a positive fundamental discriminant D≥10^10, with h_D the ordinary ideal class number and R_D the full unit regulator, √D/[2V(D)]≤h_D R_D≤√D U(D)/2.', A+' Dirichlet analytic class-number formula, Res_{s=1}ζ_K=2h_D R_D/√D.', 'short derived formulation proved here from cited classical inputs; not claimed as a new class-number theorem', 'section.tex NT-H03; NT-H01; Milne, Class Field Theory v4.03, VI, Corollary 2.12 and Example 2.13, printed p.191.', pic+' Regulator is essential: this bound alone is not a corresponding two-sided bound on h_D.')
add('NT-H04', 'For an abelian number field K/Q, ζ_K=ζ∏_{χ≠1}L(s,χ) and the analytic class-number formula turn character-by-character L(1,χ) bounds into bounds on h_K R_K. Separate estimates for the regulator and finite/small conductors are required to convert this into a bound on h_K alone or a uniform family theorem.', A+' Artin factorization and analytic class-number formula; explicit treatment of conductors below 10^10 when applying NT-H01.', 'carried corrected background; conditional only on listed independent arithmetic data', 'RETURN_ZETA_TWO IA02 and SA06 B.4a–e; equation for the residue and exact conductor product in section.tex NT-H04.', pic+' The false uniform claim |L(1,χ)|≈loglog q remains refuted by RETURN_ZETA_TWO IA09.')

add('NT-A01', 'Fix an integer g≠−1 that is not a square (hence g≠0,1). Primes p for which g is a primitive root have positive density δ(g)=Σ_{n≥1} μ(n)/[Q(ζ_n,g^{1/n}):Q], and therefore are infinite. The density includes the field-intersection correction; the universal Artin constant cannot be substituted for every g.', M+' RH for all squarefree-n Kummer fields Q(ζ_n,g^{1/n}); these fields are generally nonabelian over Q, so A alone is insufficient for the classical proof.', conditional, 'Hooley (1967), On Artin’s conjecture, J. reine angew. Math.225, unnumbered Theorem pp.219–220 (internal locator corroborated, original fresh page not yet retrieved); exact fully inspected substitute: Lenstra (1977), Theorem (3.1), printed p.206, and density (2.15), pp.205–206, specialized to K=F=Q,W=<g>,k=1. Positivity is classical Artin/Lenstra §4 and the elementary obstruction g=−1 or square.', geo+' Kummer towers of G_m; extension of RETURN_CX_GRH finite Kummer tests to an infinite prime-density theorem. Source-detail gate: original Hooley internal theorem/page not freshly inspected.')
add('NT-A02', 'For a number field K, finitely generated positive-rank subgroup W⊂K×, integer k≥1 and a finite Galois condition (F/K,C), the set of unramified good primes whose reduction of W has index dividing k and whose Frobenius lies in C has the density a of Lenstra (2.2)/(2.15). Its positivity is equivalent to the finite obstruction criterion in Theorem (4.1).', M+' Precisely RH ζ_{L_n} for every squarefree n, L_n the compositum of K(ζ_{q(ℓ)},W^{1/q(ℓ)}) for ℓ|n, q(ℓ)=ℓ^{v_ℓ(k)+1}. C is conjugacy stable.', conditional, 'Lenstra (1977), §2 definitions pp.202–206; Theorem (3.1) p.206; density (2.15) p.206; positivity Theorem (4.1) p.207.', geo+' Rank-one tori and Kummer torsors; class-field/Frobenius compatibility rather than a claim about all motives.')
add('NT-A03', 'Let K be a number field, S contain all archimedean places, and |S|≥2. If the ring R_S of S-integers is a PID, then it is Euclidean under M. Its least Euclidean function on nonzero x is Σ_{p∉S}ord_p(x)n_p, where n_p=1 if R_S×→k_p× is onto and n_p=2 otherwise. This need not be the norm algorithm.', M+' Exactly RH ζ_{K(ζ_n,R_{S′}^{×1/n})} for squarefree n and finite S′⊂S in Lenstra’s statement; the PID hypothesis remains independent.', conditional, 'Lenstra (1977), Theorem (9.1), equation (9.2), printed p.218; original page image inspected, confirming |S|≥2 (OCR misleadingly rendered >2).', pic+' Arithmetic affine curve Spec R_S, Pic=0 and unit reduction on closed fibres. This changes the Euclidean/PID gate, not all norm-Euclidean questions.')

add('NT-F01', 'For a class function f:G→C in NT-C01, put μ_f=|G|^−1Σ_g f(g), ||f||_{1,G}=|G|^−1Σ_g|f(g)|. Then |Σ_{Np^m≤x, unram}f(Frob_p^m)log Np−μ_f x|≤||f||_{1,G}E_L(x). The analogous unweighted prime estimate uses B_L(x). For a character χ, μ_χ=dim V^G and ||χ||_{1,G}≤√<χ,χ>.', M+' Only RH ζ_L and the explicit Chebotarev bounds NT-C01/C02; A suffices if L/Q abelian. No Artin holomorphy assumed.', 'proved here, conditional on precisely RH ζ_L', 'section.tex NT-F01, complete triangle-inequality and character-inner-product proof.', geo+' New quantitative trace functional on the representation ring; companion to geometry agent’s finite-recognition result.')
add('NT-F02', 'Let X→U⊂Spec O_K be finite étale of generic degree d, with splitting field L/K and r generic connected components. If S is the finite set of primes removed from U that are unramified in L, then for x≥1 the prime-power sum of #X(k_p^m)log Np differs from r x by at most r E_L(x)+d|S|log x. With no additional omitted unramified primes, the bound is r E_L(x), independent of d.', M+' RH ζ_L, finite étale Frobenius fixed-point formula, and NT-F01. A suffices if L/Q abelian.', 'proved here, conditional on precisely RH ζ_L', 'section.tex NT-F02; full proof using nonnegative permutation characters, Burnside’s lemma, and the explicit omitted-prime bound.', geo+' Concrete trace/point-count form. Includes disconnected schemes and boundary removal explicitly.')
add('NT-F03', 'For a finite G-set S and each cycle partition λ, the primes whose Frobenius acts on S with cycle partition λ have counting function δ_λ Li_2(x) with error at most δ_λ B_L(x); δ_λ is the proportion of g∈G with this cycle partition. For the canonical finite étale model of the generic algebra over the L-unramified locus, this is exactly the distribution of residue degrees. Restricting to a smaller U adds at most |S| to the error, where S is the additional removed set.', M+' RH ζ_L; A suffices in the abelian-over-Q case.', 'proved here by a finite union form of NT-C02', 'section.tex NT-F03; union of conjugacy classes, with all densities and zero-density cases treated.', geo+' Splitting types of finite étale fibres and factorizations of separable polynomials away from the discriminant.')
add('NT-F04', 'For a nonempty conjugacy-stable set D⊂G of density δ_D and a finite set S of forbidden primes of K, an unramified prime outside S with Frobenius in D and norm≤x exists whenever δ_D[Li_2(x)−B_L(x)]>|S|. This explicitly handles extra exclusions omitted from the bare least-prime theorem.', M+' RH ζ_L and NT-C02; x≥2.', 'proved here, conditional on precisely RH ζ_L', 'section.tex NT-F04; count all eligible primes, subtract at most |S|, and use positivity.', geo+' Finite open subschemes and avoidance conditions in constructive Frobenius arguments.')

add('NT-L01', 'RH implies ζ(1/2+it)≪_ε(1+|t|)^ε for every ε>0; more precisely ζ(1/2+it)=O(exp(C log|t|/loglog|t|)) for large |t| and some absolute C.', A, classical, 'Titchmarsh, The Theory of the Riemann Zeta-function, 2nd ed.(1986), Theorem 14.2 and Theorem 14.14(A); the fixed-right-half-strip estimates (14.2.5),(14.2.6) are on printed pp.336–337.', zero+' Analytic growth of the zeta realization of the unit motive; no purity theorem on Spec Z is inferred.')
add('NT-L02', 'For each fixed primitive Dirichlet character χ, L(1/2+it,χ)≪_{χ,ε}(1+|t|)^ε. For every fixed δ>0, both L(s,χ) and 1/L(s,χ) have subpolynomial growth on σ≥1/2+δ (away from the principal pole). This statement is in the t-aspect; it does not assert a uniform hybrid constant.', A+' Classical analytic continuation, functional equation and Euler product.', 'derived form proved here from an exact classical log-L bound', 'Simonič (2023), Theorem 1, equations (4)–(6), and Corollary 2; section.tex NT-L02 explains fixed-strip and critical-line passage.', zero+' Rank-one arithmetic local systems; Tate’s thesis normalization.')
add('NT-L03', 'For each fixed unitary Hecke character η over a fixed number field K, L(1/2+it,η)≪_{K,η,ε}(1+|t|)^ε. In fixed half-strips σ≥1/2+δ, reciprocal growth is subpolynomial away from poles. Pure norm twists are treated by translating the Dedekind zeta function.', M+' Standard Hecke functional equation, finite-order growth, polynomial Euler product/Ramanujan bound; norm twists handled explicitly. Constants are not uniform in conductor or infinity type.', 'derived formulation proved here conditional on M', 'Simonič (2023), Theorem 1 and §2.1 axioms; section.tex NT-L02/03 gives the application and Phragmén–Lindelöf step.', zero+' Unit-normalized rank-one Hecke realizations and CM factors; comparison with RETURN_ZETA_TWO IA01/IA06.')
add('NT-L04', 'For every fixed k≥0, ∫_T^{2T}|ζ(1/2+it)|^{2k}dt≪_k T(log T)^{k²}. This is an order-of-magnitude upper bound, not the conjectural full moment asymptotic or its leading constant.', A, classical, 'Harper (2013), Sharp conditional bounds for moments of the Riemann zeta function, Theorem 1, arXiv:1305.4618 author p.1.', zero+' Explicit formula plus averages of prime polynomials; no transfer of a random-matrix conjecture is asserted.')
add('NT-L05', 'Mertens cancellation: M(x)=Σ_{n≤x}μ(n)=O_ε(x^{1/2+ε}) for every ε>0. In fact this estimate for every ε is equivalent to RH.', A, classical, 'Titchmarsh (1986), Theorem 14.25(C), printed p.370; Theorems 14.25(A),(B) pp.369–370 give reciprocal-series convergence and converse.', specz+' The reciprocal Euler series of the unit motive and squarefree effective divisors.')
add('NT-L06', 'Liouville cancellation follows: Σ_{n≤x}λ(n)=O_ε(x^{1/2+ε}). More generally the tail Σ_{n>x}μ(n)n^−s is O_{s,ε}(x^{1/2+ε−Re s}) when Re s>1/2+ε, so Σ μ(n)/n converges to 0.', A+' NT-L05 and Abel summation.', 'short derived formulations proved here', 'section.tex NT-L06; identity λ(n)=Σ_{d²|n}μ(n/d²), then absolute summation over d; tail by full partial-summation calculation.', specz+' Euler series ζ(2s)/ζ(s), and analytic continuation of the inverse zeta realization.')
add('NT-L07', 'For x≥1, |M(x)|≤555.71x^0.99+1.94·10^14x^0.98 and |Σ_{n≤x}μ(n)/n|≤56126.71x^−0.01+9.894·10^15x^−0.02.', A, classical, 'Simonič (2023), Theorem 2, equations (7),(8); constants checked in primary full-text HTML. These effective numerical bounds become useful only at very large x.', specz)
add('NT-L08', 'For any σ>1/2, the number of nontrivial zeros with Reρ≥σ and |Imρ|≤T is exactly 0 for the Dirichlet functions covered by A, and for the Hecke functions covered conditionally by M. This replaces off-line zero-density upper bounds by zero, but does not bound multiplicity on Reρ=1/2.', 'A for Dirichlet functions; M (conditional) for the specified Hecke functions. Count nontrivial zeros only and take σ strictly greater than 1/2.', 'immediate proved consequence of the zero-location inputs', 'Definitions of A and M; section.tex NT-L08 spells out boundary and trivial-zero conventions.', zero)

add('NT-Z01', 'Montgomery’s normalized weighted pair-correlation F(α,T) satisfies F(α,T)=(1+o(1))T^(−2α)log T+α+o(1) for 0≤α<1, uniformly on every [0,1−ε], under RH. The formula concerns the weight w(u)=4/(4+u²).', A, classical, 'Montgomery (1973), The pair correlation of zeros of the zeta function, §1 unnumbered Theorem, printed p.181; definition immediately preceding it.', zero+' This is a restricted Fourier-support/α-range theorem, not full GUE.')
add('NT-Z02', 'At least (2/3+o(1)) of the nontrivial zeta zeros up to height T are simple (counted with the source’s multiplicity convention).', A, classical, 'Montgomery (1973), Corollary 2, printed p.182.', zero+' Zero multiplicities remain uncontrolled individually; does not yield Artin holomorphy at every critical-line zero.')
add('NT-Z03', 'For nonprincipal characters modulo an odd prime q, the average one-level statistic Σ_ρ f((log q/(2π))·(ρ−1/2)/i) tends to ∫f for the admissible test functions of Hughes–Rudnick with supp f̂⊂[−2,2]. The formula is unconditional; A makes all its scaled zeros real.', 'Neither for the analytic identity; A only for the interpretation as a statistic of real ordinates. Test function must have the analytic extension/decay specified by Hughes–Rudnick.', 'classical exact result; input distinction checked', 'Hughes–Rudnick (2003), Theorem 3.1, author p.5, definitions §2; arXiv:math/0208230.', zero+' Unitary family symmetry in the explicit-formula limit; finite-field monodromy is an analogy, not the proof.')
add('NT-Z04', 'For the same prime-modulus family, supp f̂⊂[−1,1] gives limiting variance ∫_{−1}^1|u|f̂(u)^2du. If supp f̂⊂[−α,α], the centered mth moment is Gaussian whenever m<2/α; odd moments vanish and even moments equal m!/[2^{m/2}(m/2)!] times the variance to power m/2.', 'Neither for these analytic formulas; A for real-ordinate interpretation. The support bound is tied to the moment order; one fixed test function is not thereby proved to have all Gaussian moments.', 'classical exact support-limited result', 'Hughes–Rudnick (2003), Theorems 4.1 and 5.1, author pp.7 and 9; definitions and variance convention as in NT-Z03.', zero+' Family moments of the low-zero trace statistic; no unrestricted random-matrix convergence claim.')
add('NT-Z05', 'For the first nonnegative scaled zero x_{χ,1}=(log q/(2π))γ_{χ,1}, liminf over prime q of min_{χ≠χ0}x_{χ,1}≤1/4. A positive proportion of characters have x_{χ,1}<β for each β≥0.633, with an explicit proportion in the source.', A+' Hughes–Rudnick’s admissible test-function construction; central zeros are included as the first nonnegative zero, exactly as ordered on source p.1.', 'classical exact locator; first-zero convention tracked in section.tex', 'Hughes–Rudnick (2003), Corollary 8.2, author p.20, and Theorem 8.3 pp.20–21. Explicit β-dependent formula is not copied without the exact convention.', zero)
add('NT-Z06', 'The full Montgomery pair-correlation formula outside |α|<1, unrestricted GUE/n-level statistics, simplicity of every zero, and central nonvanishing of every quadratic Dirichlet L-function are not established by the cited GRH consequences. Their remaining gates are correlation estimates/long prime-polynomial averages or separate nonvanishing arguments.', 'A and M provide zero location. Additional correlation or nonvanishing input is needed by the displayed methods; no claim of logical independence from GRH is made.', 'open with explicit extra gates; overstatement excluded', 'Montgomery (1973), §1 conjecture following the restricted theorem; Hughes–Rudnick (2003), support and moment restrictions in Theorems 3.1,5.1 and remarks in §8.', zero+' Distinguish finite-field equidistribution theorems from conjectural number-field family limits.')
add('NT-Z07', 'Iwaniec–Luo–Sarnak’s orthogonal one-level density for fixed even weight and squarefree level tending to infinity, support f̂⊂(−2,2), additionally assumes RH for every GL2 newform L-function in the family. A supplies the Dirichlet auxiliary part, while M alone does not supply the non-CM GL2 part.', 'A plus the independent GRH hypothesis for the specified holomorphic GL2 newforms; M alone is insufficient for this invocation.', 'conditional on extra GL2-GRH; not a consequence of A or M alone', 'Iwaniec–Luo–Sarnak (2000), global assumption printed p.56; Theorem 1.1 printed pp.58–59; proof Theorem 7.2.', zero+' Cohomology of modular curves/Shimura varieties. Finite-field purity does not settle the global automorphic zero-location gate.')
add('NT-Z08', 'The de Bruijn–Newman constant Λ for the classical deformation of the Riemann xi function equals 0. Thus every t≥0 in that normalization has only real zeros, and every t<0 has a nonreal zero.', A+' The unconditional theorem Λ≥0 of Rodgers–Tao and the classical equivalence RH⇔Λ≤0.', classical, 'Rodgers–Tao, The de Bruijn–Newman constant is non-negative, arXiv:1801.05914v5, Theorem 1 author p.3; definition and equivalence §1 pp.1–2.', zero+' A zero-divisor deformation of the zeta realization; no claim of an algebraic motive for the whole heat flow.')
add('NT-Z09', 'For every n≥1, σ(n)≤H_n+exp(H_n)log H_n, with equality only for n=1.', A, classical, 'Lagarias (2002), An elementary problem equivalent to the Riemann hypothesis, Theorem 1.1, arXiv:math/0008177v2 author p.1.', specz+' The divisor-sum arithmetic of Spec Z; the equivalence is analytic-number-theoretic, not an asserted new SGA theorem.')

add('NT-L09', 'For a fixed primitive Dirichlet character χ, Σ_{n≤x}μ(n)χ(n)=O_{χ,ε}(x^{1/2+ε}) for every ε>0. Hence for each fixed q and reduced a mod q, Σ_{n≤x,n≡a mod q}μ(n)=O_{q,ε}(x^{1/2+ε}). No constant uniform in q is asserted.', A+' NT-L02 reciprocal growth and the finite Dirichlet-character orthogonality relation.', 'derived fixed-character formulation proved here from classical analytic inputs', 'section.tex NT-L09/NT-L10; full truncated-Perron argument, with kernel locator Titchmarsh Lemma3.12 printed61–62.', specz+' Möbius cancellation in cyclotomic Frobenius classes; inverse rank-one Euler series.')
add('NT-L10', 'For a fixed unitary Hecke character η over K, Σ_{N a≤x}μ_K(a)η(a)=O_{K,η,ε}(x^{1/2+ε}), summing ideals coprime to its conductor. Finite-character orthogonality gives the same bound in each fixed ray class for the ideal Möbius function.', M+' NT-L03 reciprocal growth; ideal coefficient bound by the [K:Q]-fold divisor function; finite ray-character group for the last assertion.', 'derived formulation proved here conditional on M', 'section.tex NT-L09/NT-L10; full coefficient grouping and Perron proof. Pure norm twists are explicitly included.', pic+' Alternating effective-divisor sums on arithmetic curves, projected to ray-class torsors. This is cancellation, not prime counting.')
add('NT-Z10', 'For each fixed unitary Hecke character η, including infinite-order characters, the number of nontrivial zeros in 0≤Re s≤1 and |Im s−T|≤1 is O_{K,η}(log(|T|+3)), counting multiplicity. No GRH is needed; this does not hold for arbitrary Mellin transforms in the draft’s Schwartz class.', 'Neither A nor M. Standard Hecke analytic continuation/functional equation (Ramakrishnan–Valenza Thm7-19,p279), unconditional convexity from Simonič Theorem1 equation(2), Euler-product lower bound on Re s=2, and Jensen’s formula.', 'short arithmetic local-count formulation proved here', 'section.tex NT-Z10; full Jensen disk proof with lower bound |L(2+iT,η)|≥1/ζ_K(2), radii3 and4, and pure-norm pole exclusion. Extends the finite-order locator GM2019 AppendixA TheoremA.1 to the fixed infinite-order setting without asserting its conductor-uniform constants.', zero+' Exact arithmetic repair for root MT-M04; relevant to Masullo9.3.2.4 while leaving arbitrary Schwartz convolution ideals separate.')
add('NT-P11', 'For q≥3,(a,q)=1,x≥1, |ψ(x;q,a)−x/φ(q)|≤√x[(log x/(2π)+2)log q+log²x/(8π)+2]+e_q log x, where ψ(x;q,a)=Σ_{p^m≤x,p^m≡a mod q}log p and e_q=1 if q≡2 mod4, else0. For q=1 use NT-P01; for q=2 subtract the powers of2 exactly from ψ(x).', A+' RH ζ_{Q(ζ_q)} follows by Dirichlet factorization; cyclotomic discriminant formula; NT-C01.', 'explicit cyclotomic specialization proved here', 'section.tex NT-P11/12; full proof includes the q≡2 mod4 unramified-prime2 correction.', geo+' Quantitative closed-point congruence estimate in the cyclotomic cover. Root supplied the specialization and identified the modulus degeneracy; number_theory wrote/checks the full proof.')
add('NT-P12', 'For q≥3,(a,q)=1,x≥2, |π(x;q,a)−Li_2(x)/φ(q)|≤√x[(1/(2π)+3/log x)log q+log x/(8π)+1/(4π)+6/log x]+e_q, with e_q as in NT-P11. This is uniform in q,a,x in the stated ranges; it uses Li_2=∫_2^xdt/log t.', A+' The same cyclotomic inputs as NT-P11, using NT-C02.', 'explicit cyclotomic specialization proved here', 'section.tex NT-P11/12; singleton conjugacy classes and at most one excluded prime2.', geo+' Congruence counting on Spec Z[1/q]; finite Euler-factor boundary retained.')

add('NT-Z11', 'For D the nonzero odd squarefree integers of both signs, fixed even nonzero nonnegative Schwartz weight w, and real even Schwartz φ with supp φ̂⊂(−2,2), the w(d/X)-weighted mean over χ_{8d} of Σ_ρ φ(Imρ·log(X/(2πe))/(2π)) tends to φ̂(0)−(1/2)∫_{−1}^1φ̂(u)du. All zeros are counted with multiplicity.', A+' Only the Dirichlet-GRH input used in FPS Lemma2.5 and RH for ζ are required; the Fourier support and exact family are retained.', classical, 'Fiorilli–Parks–Södergren, arXiv:1601.06833, Theorem1.1 and definitions(1.1)–(1.2), authorp2; Theorem3.5p12 and final proofp14. See section.tex NT-Z11.', zero+' Quadratic rank-one Artin objects/double covers of open arithmetic curves. Symplectic density matches the cited hyperelliptic finite-field comparison, without transferring unrestricted support.')
add('NT-Z12', 'For D the nonzero odd squarefree integers of both signs, liminf_{X→∞} #{d∈D:|d|≤X,L(1/2,χ_{8d})≠0}/#{d∈D:|d|≤X}≥15/16. The same lower bound holds for any fixed nonnegative even nonzero Schwartz weight w(d/X). This statement is for the χ_{8d} family, not an asserted relabelling as all fundamental discriminants.', A+' NT-Z11; quadratic root number +1; real ordinates; nonnegative Schwartz approximations to squared sinc, then elementary squarefree counting.', 'classical nonvanishing consequence with complete deduction and deweighting proved here', 'section.tex NT-Z12; full functional-equation parity, Fourier approximation, limiting inequalities and smooth-majorant removal. No application of NT-Z11 at the excluded support endpoint is made.', zero+' Central divisor in a quadratic Artin family; positive-proportion result, not individual quadratic central nonvanishing.')

add('NT-H05', 'For an asymptotically exact family K_i of pairwise nonisomorphic number fields, g_i=(1/2)log Δ_i, N_q(K_i) counting prime ideals of rational-prime-power norm q, φ_q=lim N_q(K_i)/g_i, φ_R=lim r1/g_i, φ_C=lim r2/g_i, one has lim log(h_iR_i)/g_i=1+Σ_qφ_q log(q/(q−1))−φ_R log2−φ_C log(2π), and lim log Res_{s=1}ζ_{K_i}/g_i=Σ_qφ_q log(q/(q−1)). If [K_i:Q]/g_i→0, the first limit is1.', M+' RH only for ζ_{K_i}; A suffices when every K_i/Q is abelian. Exact-family limit hypotheses are independent; no normality or tower hypothesis is required.', conditional, 'Tsfasman–Vlăduţ, arXiv:math/0205129, GRH Theorem7.2 authorp44; proofpp44–49; definition2.1p15. Original theorem page image checked. Short zero-invariant specialization proved in section.tex NT-H05.', pic+' Growing arithmetic curves and their closed-point densities; class-number/regulator asymptotic, retaining R. Extends IA02/SA06 bounds from individual abelian fields to conditional general families.')
add('NT-H06', 'For the exact family of NT-H05, Σ_q φ_q logq/(√q−1)+[0.5log(8π)+π/4+γ/2]φ_R+[log(8π)+γ]φ_C≤1, summing over rational prime powers q; γ is Euler’s constant.', M+' RH only for the family Dedekind functions; A suffices for abelian-Q fields.', conditional, 'Tsfasman–Vlăduţ, arXiv:math/0205129, GRH Theorem3.1 authorp19; proofpp19–21. Constants checked on the original page image; section.tex NT-H06.', geo+' Explicit-formula positivity constraint on asymptotic closed-point counts, with real/complex-place terms. Arithmetic counterpart of the finite-field asymptotic point-count inequality, not an identification of the two settings.')
add('NT-H07', 'If n_i=[K_i:Q]→∞, Δ_i^{1/n_i}→ρ∈(1,∞), r1(K_i)/n_i→τ, and every p in a set P of rational primes splits completely in every K_i, then logρ≥log(8π)+γ+(π/2)τ+2Σ_{p∈P}logp/(√p−1). The nonnegative series must converge when P is infinite.', M+' RH for all ζ_{K_i}, NT-H06. No normality or nested-tower assumption; A suffices if all fields are abelian over Q.', 'tower/Frobenius formulation proved here from a classical inequality', 'section.tex NT-H07; complete diagonal subsequence extraction, invariant computation, finite-subset inequality and monotone limit.', geo+' Necessary discriminant budget for complete-splitting conditions in infinite arithmetic towers. Link to cote149/GT and geometry programme: prescribed Frobenius cannot be imposed at arbitrarily many small primes with bounded root discriminant.')
add('NT-H08', 'Let P be a finite set of rational primes splitting completely in K. Put C(P)=8π exp(γ+2Σ_{p∈P}logp/(√p−1)). Write rd(K)=Δ_K^{1/[K:Q]}. If rd(K)<C(P), then the maximal extension of K unramified at every finite prime and split at every prime above P has finite degree. For totally real K and only totally real extensions, rd(K)<exp(π/2)C(P) suffices. At P=∅ the exact thresholds are8πe^γ≈44.763232 and8πe^{γ+π/2}≈215.332516.', M+' Dedekind RH for every finite field in the restricted unramified extension; NT-H07 and the relative discriminant formula. Strict inequalities only. A alone does not supply RH in arbitrary nonabelian class-field towers.', 'conditional finiteness formulation proved here', 'section.tex NT-H08; complete contradiction using increasing finite Galois subextensions, constant root discriminant and a convergent signature subsequence; K=Q separated.', geo+' Finiteness of π1^ét(Spec O_K) modulo the closed normal subgroup generated by Frobenius classes above P; the totally real version also kills archimedean complex conjugation. SGA1V§7 dictionary; distinct from anabelian reconstruction.')

add('NT-R01', 'For fixed distinct reduced a_j mod q, E(x)=(logx/√x)(φ(q)π(x;q,a_j)−π(x))_{j=1}^r has a limiting probability distribution μ under logarithmic averaging: (logX)^−1∫_2^Xf(E(x))dx/x→∫f dμ for every bounded continuous f.', A+' Fixed modulus/classes; no Grand Simplicity Hypothesis is required for this continuous-test statement.', classical, 'Rubinstein–Sarnak(1994), Chebyshev’s Bias, Theorem1.1 printed174; proof§2.1 beginning178. Original p174 image inspected; section.tex NT-R01.', geo+' Limiting explicit-formula fluctuations of cyclotomic Frobenius classes. Weak convergence alone does not automatically give the measure of an ordering cone.')
add('NT-R02', 'Both {x:π(x;4,3)>π(x;4,1)} and its strict reverse have positive lower logarithmic density. The analogous two-class statement holds modulo3. This is a lower logarithmic density statement, without a claim here that the density limit exists under A alone.', A+' Rubinstein–Sarnak tail positivity; no GSH needed.', classical, 'Rubinstein–Sarnak(1994), Theorem1.2 and following discussion printed175; proof§2.2. Source page inspected as image.', geo+' Both signs of the quadratic Frobenius race occur on sets of positive logarithmic size; different from the stronger numerical Chebyshev-bias claim.')
add('NT-R03', 'Under A plus GSH, every strict r-way prime race (r≥2, distinct reduced classes mod q) has logarithmic density in(0,1). The full limiting law is permutation-invariant exactly when r=2 and c(q,a1)=c(q,a2), or r=3 and the classes form a1,a1ρ,a1ρ² with ρ≠1,ρ³=1 modq; c(q,a)=−1+#{b modq:b²=a}. In particular the mod4 nonresidue race has density strictly between1/2 and1.', A+' Extra GSH: nonnegative Dirichlet-zero ordinates, with multiplicities, are Q-linearly independent. This includes no central zeros or repeated ordinates and is not discharged by A or M in this argument.', 'conditional on additional GSH; not claimed from zero location alone', 'Rubinstein–Sarnak(1994), formula(1.2), Remark1.3 printed176; Theorem1.4 and accompanying bias discussion printed177, proofProposition3.1. Original images inspected.', geo+' Cyclotomic Frobenius race; exact remaining gate is frequency independence. Symmetry of the full law is distinguished from equality of a single race probability.')
add('NT-R04', 'Under A plus GSH, for each fixed r≥2, max over distinct reduced classes a1,…,ar modq of |δ{x:π(x;q,a1)>⋯>π(x;q,ar)}−1/r!|→0 as q→∞.', A+' Same extra GSH as NT-R03; r is fixed as q grows.', 'conditional on additional GSH', 'Rubinstein–Sarnak(1994), Theorem1.5 printed177, proof§3.2; original theorem page inspected.', geo+' Asymptotic dissolution of fixed-length cyclotomic prime-race bias; no uniform conclusion for r growing with q.')

add('NT-Z13', 'Under RH, |S(t)|≤(1/4)logt/loglogt+O(logt logloglogt/(loglogt)^2). For a primitive finite-order Hecke character η over degree-n K, put Q=Δ_K Nf, Γ_R parameters μ_j∈{0,1}, C=Q∏(μ_j+3), C(t)=C(|t|+1)^n, D(t)=loglog(C(t)^(3/n)). Under its GRH, |S_η(t)|≤logC(t)/(4D(t))+O(logC(t)logD(t)/D(t)^2), with an absolute constant. For fixed K,η the leading coefficient in t-aspect is n/4.', A+' for ζ and Dirichlet characters; conditional M for finite-order Hecke characters. The cited general theorem requires gamma parameters real or in conjugate pairs, so arbitrary infinite-order Hecke characters are not silently included.', 'classical bound with exact analytic-hypothesis verification', 'Carneiro–Chandee–Milinovich2015 Theorem1 authorp2, proof§3 pp3–5; §4 axioms p6; Theorem5 equation(4.4) p7, proofpp7–12. section.tex NT-Z13 checks all finite-order Hecke axioms.', zero+' Quantitative argument variation for rank-one local systems. Conductor normalization is retained; source archimedean pairing restriction is explicit.')
add('NT-Z14', 'For each fixed primitive finite-order Hecke character η over degree-n K, under its GRH: m_η(γ)≤(n/2)logγ/loglogγ+O_{K,η}(logγ logloglogγ/(loglogγ)^2); consecutive distinct large positive ordinates obey γ′−γ≤π/loglogγ+O_{K,η}(logloglogγ/(loglogγ)^2). Every large T is within π/(2loglogT)+the same error of a zero ordinate. For ζ, n=1 and A suffices.', 'NT-Z13, classical Hecke functional equation and Stirling; A for functions over Q, conditional M for general finite-order Hecke characters. Fixed field and character; no simplicity or spacing-distribution assumption.', 'classical consequences in a fixed-character formulation, fully proved here', 'section.tex NT-Z14: complete boundary-log jump, critical-line phase identity, existence of arbitrarily high zeros, preliminary gap<1, one-sided endpoint passage, and final division. Source for argument bound: CCM2015 Theorem5.', zero+' Multiplicity and covering-radius constraints on the explicit-formula zero spectrum, without a geometric multiplicity-one assertion; refines NT-Z06.')
add('NT-Z15', 'For primitive finite-order Hecke η, with n,C as NT-Z13 and D=loglog(C^(3/n)), ord_{s=1/2}L(s,η)≤logC/(2D)+O(logC logD/D²), with a universal constant. For primitive Dirichlet χ of conductor q→∞ this is ≤(1/2+o(1))logq/loglogq.', A+' for Dirichlet characters; conditional M for finite-order Hecke characters. Degree n remains inside the conductor logarithm when fields vary; gamma factors have no pole at1/2.', 'classical theorem specialized with exact conductor and degree dependence', 'CCM2015 Theorem5 equation(4.5), authorp7, proofendingp12; Example8p14. section.tex NT-Z13 verifies axioms and NT-Z15 explains equality of completed/uncompleted orders.', zero+' Central multiplicity of rank-one arithmetic L-functions; this is an upper bound rather than central nonvanishing or algebraic rank identification.')
add('NT-Z16', 'For primitive finite-order Hecke η, with n,C as NT-Z13 and D=loglog(C^(3/n)), there is a zero1/2+iγ with |γ|≤π/(2D)+O(logD/D²) as C^(3/n)→∞, with a universal constant. For primitive Dirichlet conductor q→∞, min|γ|≤(π/2+o(1))/loglogq. A central zero is allowed.', A+' for Dirichlet characters; conditional M for finite-order Hecke characters, with the §4 analytic hypotheses checked in NT-Z13. This is not a bound for the first strictly positive ordinate.', 'classical low-zero theorem with exact growth condition', 'CCM2015 Theorem7 and its proof, authorp13. section.tex NT-Z16 retains degree-normalized conductor and central-zero convention.', zero+' An individual low-zero guarantee complements family-density rows NT-Z03–05 and NT-Z11. It does not imply a distribution law or central nonvanishing.')

add('NT-P13', 'For every x≥4 there is a prime in [x,x+(22/25)√xlogx]. Thus consecutive primes with p_n>3 satisfy p_{n+1}−p_n≤(22/25)√p_n logp_n. Moreover limsup_n (p_{n+1}−p_n)/(√p_n logp_n)<21/25.', A+' Only RH ζ is needed.', classical, 'Carneiro–Milinovich–Soundararajan2019, arXiv1708.04122v2 Theorem5 and Corollary4 authorp5; proofs§6 pp21–26 and §5. section.tex NT-P13 supplies the closed-left-endpoint passage.', specz+' Explicit prime detection and a sharper asymptotic constant have distinct quantifiers; no claim of current optimality.')
add('NT-P14', 'For primes p→∞, both the least quadratic nonresidue n_p and the least prime quadratic residue r_p satisfy limsup n_p/log²p<0.7615 and limsup r_p/log²p<0.7615. The residue prime is required to have Legendre value1.', A+' Dirichlet GRH as in the cited theorem; these are asymptotic statements without a numerical all-p threshold.', classical, 'Carneiro–Milinovich–Quesada-Herrera–Ramos, arXiv2404.08380v2 (2025), Theorems1/2 authorp2; proofThm6§4 pp13–17 and §4.4pp16–17. Primary p2 image inspected.', geo+' Both nontrivial and trivial quadratic Frobenius classes have small prime representatives. Refines asymptotic constants without replacing NT-P07’s explicit threshold.')
add('NT-P15', 'For each fixed character order ℓ≥2 and nonprincipal Dirichlet χ modulo q, n_χ=min{n:χ(n)∉{0,1}} is prime and obeys n_χ≤(c_ℓ+o_ℓ(1))log²q. One may take c2=.7615,c3=.6707,c4=.6131,c5=.5765; for ℓ≥6, c_ℓ=(1/4)[1−{ℓ/(ℓ−1)}log((3ℓ−4)/ℓ)/log(ℓ−1)+1/(ℓ−1)]^(−2).', A+' Primitive or imprimitive characters; order ℓ is fixed. Primes dividing q are excluded by χ(n)≠0. No growing-order uniformity claimed.', classical, 'CMQR2025v2 Theorem6 authorp5, Corollary7p6, proof§4; source definition(1.8)p5. section.tex NT-P15 includes the complete elementary proof that n_χ is prime.', geo+' Detects a prime outside the kernel of a rank-one cyclotomic representation; improves the numerical asymptotic subgroup detector for specified order.')
add('NT-P16', 'Uniformly over reduced classes a modq, limsup_{q→∞} max_{(a,q)=1}P(a,q)/(φ(q)logq)^2<8/9, where P(a,q) is the least prime in that progression.', A+' Dirichlet GRH; asymptotic q→∞, with no explicit numerical threshold asserted.', classical, 'CMQR2025v2 Theorem3 authorp3; proof§5 pp18–22, especially(5.15)–(5.16) showing errors depend on fixed test F and not a. Primary p3 image inspected.', geo+' Uniform asymptotic cyclotomic Frobenius detection; complements all-q NT-P06. Published numerical optimization is cited, not independently rerun.')
add('NT-L11', 'For every fixed real k≥0 and large X, Σ_{X≤|d|≤2X, d fundamental}|L(1/2,χ_d)|^k≪_k X(logX)^{k(k+1)/2}. Both signs of fundamental discriminants are included.', A+' Only GRH for the quadratic Dirichlet family is needed.', classical, 'Harper2013 arXiv1305.4618v1 Theorem2 authorp15; proof§5 pp15–17 via Propositions3/4. Original theorem page image inspected.', zero+' Central moments of the full quadratic Artin family in a discriminant shell; upper order bound, not a leading-constant asymptotic or reciprocal-moment assertion.')
add('NT-L12', 'For each fixed α>0, meas{t∈[T,2T]:|ζ(1/2+it)|≥(logT)^α}≪_α T(logT)^(−α²). For fixed α>1/2, #{fundamental d:X≤|d|≤2X, |L(1/2,χ_d)|≥(logX)^α}≪_α X(logX)^(−(α−1/2)²/2).', A+' Harper moment bounds NT-L04/NT-L11 and Markov inequality; threshold exponents fixed.', 'complete optimized-moment deduction written here', 'section.tex NT-L12: Markov with fixed k=α for ζ and k=α−1/2 for the quadratic family, followed by the displayed square completion.', zero+' Explicit exceptional-set bounds for rank-one arithmetic central values; no negative moments, small-value control or full limiting distribution is inferred.')

add('NT-H09', 'Let K≠Q have degree n and root discriminant ρ. Let S be a finite set of prime ideals with q_𝔭=N𝔭 and positive integers m_𝔭. Suppose finite Galois K_i/K are unramified at finite primes, [K_i:K]→∞, each residue degree above 𝔭∈S is≤m_𝔭, and r1(K_i)/[K_i:Q]→τ. Under RH for all ζ_{K_i}, logρ≥log(8π)+γ+(π/2)τ+(2/n)Σ_{𝔭∈S}logq_𝔭/(q_𝔭^{m_𝔭/2}−1).', M+' Only the Dedekind RH hypotheses for the given fields and TV NT-H06 are needed. No nested-tower condition; S consists of arbitrary base-field prime ideals, not necessarily rational degree-one primes.', 'relative closed-point and residue-degree formulation proved here', 'section.tex NT-H09: complete finite residue-degree subsequence, exact prime-power multiplicity, diagonal family extraction, discriminant/signature normalization and monotonicity proof. TV2002 GRHThm3.1p19.', geo+' A discriminant budget for bounded-order Frobenius at arbitrary closed points of Spec O_K; coincidence of absolute prime-power norms is explicitly handled.')
add('NT-H10', 'For G_K=π1^ét(Spec O_K), let N be the closed normal subgroup generated by Frob_𝔭^{m_𝔭}, 𝔭∈S. Put C=8π exp(γ+(2/[K:Q])Σ_{𝔭∈S}logN𝔭/((N𝔭)^{m_𝔭/2}−1)). If rd(K)<C, M implies G_K/N finite, equivalently N open. For totally real K, in the quotient killing complex conjugations, rd(K)<exp(π/2)C suffices. K=Q holds unconditionally.', M+' Dedekind RH for finite subextensions of this quotient, NT-H09, relative discriminant formula and the finite-étale Galois dictionary. Strict inequalities only.', 'full conditional fundamental-group quotient finiteness proof written here', 'section.tex NT-H10: infinite quotient yields growing finite Galois fields; Frobenius power relations bound residue degree; signature subsequence and NT-H09 contradict threshold. Minkowski handles Q.', geo+' Generalizes NT-H08 from complete rational-prime splitting to arbitrary closed points and finite Frobenius-order relations. Finite index of a closed normal closure is distinguished from finite topological generation of that subgroup.')

add('NT-Z17', 'For primitive unitary Hecke η over degree-n K, excluding pure norm characters, set Cη(T)=Qη∏_{j=1}^n(|μ_j+iT|+3) and R=loglog(Cη(T)^(3/n)). Under its GRH, ord_{1/2+iT}L≤logCη(T)/(2R)+O(logCη(T)logR/R²); as Cη(T)^(3/n)→∞ there is an η zero ordinate γ with |γ−T|≤π/(2R)+O(logR/R²), with universal constants. All fixed unitary Hecke characters, including pure norm twists, consequently satisfy NT-Z14’s multiplicity and gap asymptotics.', M+' Only GRH for η is needed, with standard primitive unitary Hecke continuation/functional equation. A already suffices for a norm-shift of a Dirichlet L-function. Uniform conductor formulas exclude pure norm characters; their fixed-character asymptotics follow by translating ζ_K. No individual Sη bound is asserted here.', 'complete conjugate-product transfer proved here', 'section.tex NT-Z17: F_T=L(s+iT,η)L(s−iT,barη) has degree2n, paired gamma parameters, θ=0 and conductor Cη(T)²; central order doubles and zeros transfer via T±u. Exact applications of CCM2015Thm5eq4.5p7/Thm7p13, with norm-twist pole exception handled separately.', zero+' Conjugate-dual symmetrization of unitary rank-one objects, including infinity types without an algebraic motive. Resolves the gamma-pairing gate for zero quantities, while the individual argument-bound gate remains separate.')
add('NT-Z18', 'As primes q→∞, the mean central multiplicity over all q−2 nonprincipal characters modulo q is≤1/2+O(1/logq). In particular at least (1/2−O(1/logq))(q−2) of these Dirichlet L-functions have nonzero central value.', A+' Hughes–Rudnick one-level mean theorem; GRH is used for positivity on real zero ordinates. No simplicity, LI or multiplicity parity assumption.', 'classical one-level corollary with entire deduction written here', 'section.tex NT-Z18; Hughes–Rudnick2003 Definition2.1p4 and Theorem3.1p5. Exact admissible sinc-squared test has support[-2,2], f(0)=1 and integral1/2; positivity and indicator≤multiplicity complete the proof.', zero+' Nonvanishing proportion for the full prime-conductor unitary Artin family, distinct from the χ_{8d} symplectic-family NT-Z12 and from nonvanishing for each character.')

add('NT-C06', 'For a ray class group Cl_m(K) of size h, n=[K:Q], ray class field H, let a_m=logΔ_K+h^−1Σχ logNfχ=logΔ_H/h≤logΔ_K+(1−1/h)logNm0. For every class c, |ψ_c^m(x)−x/h|≤√x[(logx/(2π)+2)a_m+(log²x/(8π)+2)n]+e_m logx (x≥1), and |π_c^m(x)−Li_2(x)/h|≤√x[(1/(2π)+3/logx)a_m+(logx/(8π)+1/(4π)+6/logx)n]+e_m (x≥2). Here e_m counts primes dividing m0 that are unramified in H/K; e_m≤ω_K(m0).', M+' Only RH ζ_H is needed, plus classical ray class-field existence/reciprocity and conductor–discriminant. A suffices whenever H/Q is abelian, including every K=Q case. No arbitrary-K implication is inferred merely from K/Q abelian.', 'complete average-conductor specialization and boundary-correction proof written here', 'section.tex NT-C06; GM2019Thm1.1p2/Cor1.2p3; Milne CFT V3.5–3.6 printed158; Neukirch ANT VII(11.7)–(11.10) printed533–535/PDF541–543, supplied conductor–discriminant proof read on primary images.', pic+' Finite abelian quotient of π1 of Spec O_K with finite modulus removed and real sign conditions; mean Artin conductor controls classwise error without a multiplicative class number. Degenerate modulus primes are explicitly removed.')
add('NT-C07', 'Every ordinary ideal class of K contains a prime ideal of residue degree one over Q with norm≤[h_K(4logΔ_K+2.5[K:Q])+5]^2 under RH for the Hilbert class-field Dedekind function and ζ_Q. The analogous statement for narrow ideal classes uses h_K^+ and the narrow class field. Their classwise count errors are NT-C06 with a_m=logΔ_K and e_m=0.', M+' Only RH for the relevant (ordinary or narrow) class-field ζ_H and ζ_Q. A supplies ζ_Q and suffices for the full conclusion if H/Q is abelian. K=Q is handled directly by prime2.', 'full unramified class-field specialization proved here', 'section.tex NT-C07; Bach–Sorenson1996Thm5.1 printed1729/PDF13, §2 RH hypotheses printed1720; relative discriminant formula for finite-unramified extensions and NT-C06.', pic+' Individual prime representatives in Pic(Spec O_K), with real sign refinement for narrow classes. Distinct from class-group generation; no arbitrary extra prime exclusion is added to the source theorem.')

add('NT-C08', 'In NT-C06, put δ=1/h and U_m(x)=x^−1/2[(3/(2π)+9/logx)a_m+(3logx/(8π)+5/(4π)+18/logx)n]+2e_m/x. Every ray class c has real B_c and positive A_c such that |Σ_{p∤m0,[p]=c,Np≤x}1/Np−δloglogx−B_c|≤U_m(x), and |log∏_{p∤m0,[p]=c,Np≤x}(1−1/Np)^−1−δloglogx−logA_c|≤U_m(x)+n/(2 floorx), for every x≥2. Thus the normalized product tends to A_c and finite prime lists give certified intervals for both constants.', M+' Exactly the same RH ζ_H input as NT-C06, plus elementary partial summation and the number-field degree formula. A suffices for H/Q abelian, in particular K=Q. No simplicity, LI or extra zero-density hypothesis.', 'complete explicit Mertens-constant and Euler-product tail proof written here', 'section.tex NT-C08: exact Stieltjes boundary at2, absolute tail integral of the NT-C06b error, all three elementary integrals, and higher-prime-power tail≤n/(2 floorx). Based only on the checked GM2019 bound through NT-C06.', geo+' Reciprocal-norm measure and regularized Euler product for a prescribed abelian Frobenius class. Gives rigorous arithmetic constants from finite closed-point counts; no identification with a motivic period is inferred.')

add('NT-L13', 'For primitive unitary non-pure-norm Hecke η over degree-n K, let C=Qη∏j(|μ_j+iT|+3), y=loglogC. If y≥10, |L(1/2+iT,η)|≤exp[(3/(8y)+23n/(25y²))logC]. In particular |L|≤C^ε when y≥max{10,3/(4ε),sqrt(46n/(25ε))}; the constants are uniform in field, character and height. For varying degree, y→∞ and n=o(y²) imply |L|≤C^{o(1)}.', M+' Precisely GRH for η and RH for ζ_Q, plus standard unitary Hecke analytic theory; Ramanujan Euler-root bounds are automatic. A suffices for a norm shift of a nonprincipal primitive Dirichlet function. Pure norm characters are excluded from this pole-free specialization.', 'precise classical uniform bound with full conductor/axiom specialization and threshold deduction', 'section.tex NT-L13; Chandee2009 Cor1.1 authorp3, axioms/conductor(2)–(6)p2, proof(14)–(15)p7, main logarithmic inequality proofpp4–6. Primary p2–3 images inspected; full Cor1.1 deduction read. Larger conductor is substituted before choosing x, not by uncontrolled asymptotic equivalence.', zero+' Critical values of unitary rank-one arithmetic objects, with explicit finite/infinite conductor and degree dependence. Supplies genuine family uniformity beyond fixed-character NT-L02/03; no central lower bound or negative moments.')

add('NT-L14', 'For primitive unitary non-pure-norm Hecke η over degree-n K, C1(η,T)=Qη(2π)^−n∏j|1+μ_j+iT|. If logC1≥23n, V_n(C1)^−1≤|L(1+iT,η)|≤U_n(C1), with every explicit coefficient and n dependence of U_n,V_n displayed in section.tex. For fixed n their leading orders are (2e^γ loglogC)^n and (12e^γ loglogC/π²)^n for the reciprocal; these are bounds, not pointwise asymptotic equalities.', M+' Precisely GRH for η and RH ζ_Q; latter used in source Lemmas3.6–3.7. Unit Hecke Euler roots prove Ramanujan automatically. A suffices for nonprincipal Dirichlet norm shifts. Entire-completion/pure-norm exception retained.', 'precise cited classical theorem with all Hecke hypotheses and constants specialized', 'section.tex NT-L14; Lumley2018 Thm2.1–2.2 authorpp3–4, Cor2.3p5; axioms§1.1pp2–3; proof§4.1pp11–13/§4.2pp14–16. Original p3–4 images checked, including constants(2.1)–(2.3) and J1 upper-bound direction.', zero+' Uniform critical-boundary upper and reciprocal bounds for unitary rank-one arithmetic objects; exact conductor normalization and finite threshold precede class-number applications.')
add('NT-H11', 'Let E/K be finite abelian, n=[K:Q], and Cχ=Δ_K Nfχ·2^(aχ+r2(K))/(2π)^n for each nontrivial character χ of Gal(E/K), where aχ counts odd real signs. Put D(E/K)=(w_E/w_K)√(Δ_E/Δ_K)2^(r1K−r1E)(2π)^(r2K−r2E). If logCχ≥23n for every χ≠1, then D∏χ V_n(Cχ)^−1≤h_E R_E/(h_K R_K)≤D∏χ U_n(Cχ). In general retain F_small=∏_{χ≠1,logCχ<23n}|L(1,χ)| exactly and apply the products only to the other characters.', M+' RH ζ_E and RH ζ_Q suffice: finite-order Hecke factors are entire, so ζ_E RH implies their GRH. A suffices if E/Q is abelian. Full unit regulators and ordinary class numbers are used; class numbers alone need an additional regulator estimate.', 'complete relative formulation and ramified Euler-factor proof written here', 'section.tex NT-H11: inertia/Frobenius character restriction proves ζ_E=ζ_K∏χ≠1Lχ at all finite primes; residue ratio and exact archimedean conductor computation then apply NT-L14. Class-field identification Milne V3.5–3.6p158; analytic class-number formula VI Cor2.12/Example2.13p191.', pic+' Relative Picard and regulator comparison for finite abelian arithmetic covers over any base field. Extends the earlier Q-abelian framework while retaining every small conductor, roots-of-unity and signature factor.')


add('NT-L15', 'For a fixed primitive unitary Hecke η, let Mη(x) sum the ideal coefficients of 1/L(s,η) up to norm x. If Bη=limsup_X(logX)^−1∫_1^X|Mη(x)/x|²dx<∞, then GRH holds, all nontrivial zeros are simple, and Σρ|ρL′(ρ,η)|^−2≤Bη. Hence |L′(ρ,η)|^−1≤√Bη|ρ| and is o(|ρ|), and Σ_|Imρ|≤T|L′(ρ,η)|^−2=o(T²).', 'Additional weak mean-square hypothesis Bη<∞ plus the standard primitive unitary Hecke continuation, dual functional equation and Euler product. Neither A nor M is needed once this hypothesis is imposed, and neither is asserted to imply it. Pure norm characters are included.', 'complete fixed-Hecke extension with exact limsup/Bessel constant proved here; classical ζ case explicitly attributed', 'section.tex NT-L15 and weak_mertens.tex: complete Laplace continuation, conjugate-dual reflection, pole-order bound, Abel-weighted finite Bessel argument, and dominated-convergence tail proof. Classical ζ source Titchmarsh1986 §14.29 pp376–380, (14.29.1)–(14.29.4); primary pp376–377 image checked.', zero+' Inverse Euler weights on squarefree effective divisors of Spec O_K. Quantitative analytic condition, not a new purity or motivic theorem; no limiting distribution or full Fourier completeness inferred.')
add('NT-Z19', 'Under the Hecke weak mean-square hypothesis NT-L15, the canonical quotient E/closure(ψη*E), Mψη=entire pole-removed completed Ξη, equals the quotient by all zero evaluations and is topologically s(Z). It has an absolute Schauder basis with Mellin evaluation coordinates. Every convolution is nuclear; its diagonal ℓ² realization is trace class with Hilbert trace Σρ Mh(ρ). For h#(x)=e^(−x)conj(h(−x)), h*h# acts positively with trace Σρ|Mh(ρ)|².', 'Precisely Bη<∞ from NT-L15, standard fixed-Hecke analytic structure, and proved canonical-basis/trace equivalences MT-M12/M13 or MT-M16/M17. This stronger arithmetic condition supplies GRH, simplicity and derivative lower bounds; A/M alone do not supply it.', 'complete cross-result deduction with positivity normalization proved here', 'section.tex NT-Z19 and weak_mertens.tex; NT-L15 gives |L′(ρ)|≥Bη^(−1/2)|ρ|^−1, so MT-M16 applies with every multiplicity1; MT-M17 plus direct Mellin involution calculation gives trace and positivity. Parent full proofs independently read by this agent and exact peer events recorded.', zero+' Conditional analytic realization of the zero divisor; no identification with an independently constructed arithmetic or motivic cohomology is asserted. Work/run GRH_NIGHT/number_theory.')


add('NT-H12', 'Fix n≥2, ℓ≥2 and ε>0. For each degree-n field K satisfying RH ζ_K, |Cl_K[ℓ]|≪_{n,ℓ,ε}D_K^(1/2−1/(2ℓ(n−1))+ε). The exact finite count N_K^{degree1,unram}(x)≥Li_2(x)−B_K(x)−n√x−nω(D_K) is also proved, with B_K the explicit NT-C02 error.', M+' Only RH for the field’s own Dedekind ζ_K is needed, together with the unconditional Ellenberg–Venkatesh small-prime torsion lemma. A supplies this RH when K/Q is abelian. No normal-closure or class-field RH is required by the supplied proof.', 'classical exponent with complete narrower analytic-input deduction written here', 'section.tex NT-H12 and class_torsion.tex. Ellenberg–Venkatesh author preprint Lemma3/proofp6, Proposition1p7; original images read. NT-C02 for trivial K/K supplies degree-one primes; norm under ideal extension excludes proper subfields; epsilon choice and bounded-discriminant cases are fully proved. Milne ANT v3.08 Hermite Thm8.43pp151–152.', pic+' Torsion line bundles on Spec O_K; Arakelov source includes archimedean places. The new input reduction counts degree-one closed points rather than assuming full splitting. Classical EV exponent is not presented as new.')
add('NT-H13', 'For prime ℓ, the number of cyclic degree-ℓ K-extensions unramified at finite places and split at all real places is (|Cl_K[ℓ]|−1)/(ℓ−1), hence satisfies the NT-H12 exponent. For any integer ℓ≥2, U=Spec O_K[1/ℓ], S={primes above ℓ}, |H¹_et(U,μℓ)|=ℓ^(r1+r2−1+|S|)gcd(ℓ,w_K)|Pic(U)[ℓ]|≤ℓ^(r1+r2+|S|)|Cl_K[ℓ]|, hence the same discriminant exponent for fixed n,ℓ.', M+' Only RH ζ_K for n≥2 and NT-H12, plus ordinary global class field theory, étale Kummer sequence and S-unit theorem. A suffices for abelian K/Q. Real-place splitting retained for ℓ=2; μℓ need not be constant and torsors need not be connected.', 'complete cyclic-cover count and Kummer-cohomology deduction written here', 'section.tex NT-H13 and class_torsion.tex. Milne ANT v3.08 Remark4.11/footnotep72, S-unit Thm5.11/proofp90; Milne CFT V3.5–3.6. Stacks§59.28Tag03PK, Lemma59.28.1 and following cohomology sequence; Lemma59.28.5Tag040Q. Full quotient-torsion cardinality, roots-of-unity factor and cyclic-kernel count proved.', pic+' Literal bounds on abelian finite étale covers with stated real conditions and on H¹ of μℓ-torsors over the arithmetic open U. No unjustified injection on localized Picard torsion and no bound for arbitrary nonabelian covers or unreduced Selmer problems.')


add('NT-L16', 'For inverse Hecke coefficient sum Mη, set Iη(X)=∫_1^X|Mη(x)/x|²dx. A critical-line zero ρ of multiplicity m with cρ=L^(m)(ρ)/m! forces limsup Iη(X)/(logX)^(2m−1)≥1/[(2m−1)((m−1)!)²|ρcρ|²]. More strongly the reciprocal-leading-coefficient terms sum over all distinct critical zeros of exact multiplicity m with the same denominator. Thus limsup Iη/(logX)^a=∞ for 0≤a<2m−1. Any zero with Reρ>1/2 forces that failure for every finite a≥0.', 'No A/M required for these implications; the specified zero and its location/order are explicit premises. M supplies critical-line location for nontrivial zeros. Standard primitive unitary Hecke continuation and inverse Euler coefficients as NT-L15.', 'complete multiplicity-sensitive Abel/Laplace necessary-growth proof written here', 'section.tex NT-L16 and mertens_obstruction.tex. Finite limsup gives A(Y)≤(B+ε)Y^(2m−1)+C. The normalized waves σ^(m−1)y^(m−1)e^(iγy)/sqrt((2m−2)!) have Gram entries [σ/(σ−i(γ−ν))]^(2m−1). Derivatives of the leading pole and finite Gram-Bessel yield the sharpened exact constant and infinite-sum version. Single-pole polynomial-wave model attains the analytic constant; no Hecke attainment claimed. Right-half zero contradicts holomorphic Laplace continuation under any polynomial-log bound.', zero+' Quantitative obstruction associated with the length of a spectral local algebra. This is a limsup lower bound, not a mean-square asymptotic or an asserted multiplicity bound.')
add('NT-L17', 'For odd prime r≥3 and prime p≠r, E=Q(ζ_r,p^(1/r)) has ζ_E=ζ_{Qζ_r}H^(r−1), where H is an entire nontrivial finite-order Hecke L-function with infinitely many nontrivial zeros. Hence ζ_E has infinitely many zeros of multiplicity≥r−1 and its ideal-Möbius weak-Mertens limsup I_E(X)/logX is infinite, unconditionally. Under RH ζ_E, each H zero of actual ζ_E order m satisfies NT-L16’s explicit log^(2m−1) lower bound. Also no faithful continuous full-jet Hilbert completion can make all h*h# convolution operators positive, although M implies nonnegative Hilbert traces.', 'Elementary prime-r Kummer group calculation (CX-ALG-024); unconditional abelian Hecke factorization including ramified primes, Hecke holomorphy and finite-order zero count; NT-L15/L16 and MT-M20. No A, M, PF26 or general Artin-holomorphy conjecture for the multiple-zero/weak-mean/Hilbert obstruction. RH ζ_E or M is needed only for the specified critical-zero constant and trace-positive conclusion.', 'complete explicit arithmetic obstruction proved here; no assertion for every nonabelian Galois field', 'section.tex NT-L17 and mertens_obstruction.tex. Q-conjugation permutes the r−1 nontrivial characters of Gal(E/Qζ_r) transitively and preserves all ideal norms/Euler factors; NT-H11 proves all-prime abelian factorization. RV Thm7-19p279 gives entire nontrivial Hecke factor; GM2019 AppendixA ThmA.1p26 gives infinitely many strip zeros. NT-L15 excludes finite weak mean; MT-M20 excludes faithful positive full-jet completion.', zero+' Repeated rank-one Hecke realization inside the affine Galois-cover zeta object. The explicit S3 example E=Q(cuberoot2,sqrt−3) has at least double zeros. Compatible with GRH and MT-M18 adapted blocks; positivity of trace is retained separately from faithful operator positivity.')

add('NT-E01','For any elliptic curve E/K over any number field, CM or non-CM, the number of good primes of norm≤x with cyclic reduction is δ_E/K x/logx+o_E,K(x/logx), where δ=Σ_m μ(m)/[K(E[m]):K]≥0 is absolutely convergent. Density zero is retained.','M, or precisely RH ζ_{K(E[m])} for each squarefree m including1. No elliptic GL2-L GRH and no general Artin holomorphy assumption.','classical density theorem with exact analytic-family identification proved here','elliptic_reductions.tex/section.tex NT-E01. Murty1983 Theorem1 printed153, entire proof153–155; Campagna–Stevenhagen2023 §2, Lemma2.1/Cor2.2/Props2.3–2.4, authorv2pp6–9. CRT compositum and finite-torsion input identification checked.','GRH_NIGHT/number_theory; finite monodromy covers trivializing E[m] on arithmetic opens, π1 étale and the torsion sheaf of H1. Finite torsion-field RH is distinguished from the elliptic infinite-image L-function.')
add('NT-E02','For non-CM E/K, let N be the product of critical primes dividing30D_K, below bad reduction, or with nonmaximal modℓ image. Put C_N={g∈Gal(K(E[N])/K):g acts nontrivially on E[ℓ] for everyℓ|N}. Then δ_E/K=(|C_N|/|G_N|)∏_{ℓ∤N}(1−1/((ℓ²−1)(ℓ²−ℓ))). C_N empty implies only finitely many cyclic reductions unconditionally; nonempty implies positive density underNT-E01. Full K-rational E[ℓ] is a sufficient obstruction for any E/K, but general-field entanglement can also force zero.','Unconditional Campagna–Stevenhagen Thm1.1 factorization and elementary finite Frobenius arguments; NT-E01/M only for positive-density realization. No independence of critical division fields assumed.','complete finite-group certificate and obstruction proof from cited factorization','elliptic_reductions.tex/section.tex NT-E02. Campagna–Stevenhagen Thm1.1 authorp3, factorization proofpp9–10; actual nontrivial-entanglement examples Thm5.1/§5pp14–16. Full finite inclusion–exclusion/product positivity/reduction proof written here.','GRH_NIGHT/number_theory; finite étale torsion covers and union of Frobenius restriction kernels. No prescribed-point generation or Koblitz prime-order conclusion.')
add('NT-E03','For fixed non-CM E/Q, a_p=p+1−#E(Fp), P_E,a(x)=#{good p≤x:a_p=a}, uniformly in integer a: P_E,a(x)≪E x^(4/5)/(logx)^(3/5), and P_E,0(x)≪E x^(3/4)/(logx)^(1/2).','M suffices. Narrower sufficient input: A plus RH ζ_{Q(E[ℓ])} for all sufficiently large primesℓ. Auxiliary B/U and B/H quotients are abelian; all needed Artin holomorphy is known, not an extra conjecture.','cited classical bound with complete narrower-input audit','elliptic_reductions.tex/section.tex NT-E03. Zywina2015 authorThm1.2p1, GRHdefinitionp3, complete§4pp10–11; Murty–Murty–Saradha1988 Lemma4.4 and whole proof printed269–270. NT-H11 transfers RH to L^U/L^H since U/H are abelian.','GRH_NIGHT/number_theory; finite modℓ elliptic H1 monodromy and abelian intermediate arithmetic covers. Does not prove non-CM GL2 RH or the Lang–Trotter asymptotic.')
add('NT-E04','For fixed non-CM E/Q and any imaginary quadratic k, P_E,k(x)=#{good p≤x:Q(sqrt(a_p²−4p))≅k}≪E h_k^(−3/5)x^(4/5)/(logx)^(3/5)+x^(1/2)(logx)^3, uniformly in k. P_E,k(x)=0 if d_k>4x.','M, or RH ζ_k and ζ_Q plus RH for the auxiliary fields L_{k,ℓ}^U in Zywina§5: L_{k,ℓ}/H_k is cut out by E[ℓ] together with the modulusℓ ray-class representation of imaginary quadratic k; ℓ split in k and sufficiently large. The relevant B/U extension is abelian, so no additional AHC.','cited classical uniform theorem with exact auxiliary-field family retained','elliptic_reductions.tex/section.tex NT-E04. ZywinaThm1.3(i)p2; joint representation§3.2–3.3pp7–10; algebraic reduction§5pp11–13; full conditional proof§5.1pp13–14; discriminant cutoffLemma5.5p13.','GRH_NIGHT/number_theory; Frobenius endomorphism fields detected using finite torsion and ray-class monodromy. Uniform h_k dependence retained for a later counting deduction.')
add('NT-E05','For fixed non-CM E/Q, the number of distinct imaginary quadratic Frobenius fields from good primes p≤x satisfies |D_E(x)|≫E x^(2/7)/[(logx)^(4/7)(loglogx)^(6/7)] as x→∞.','M suffices; precisely the family of Dedekind RH inputs in NT-E04 for all imaginary quadratic k plus A for NT-H02 class-number lower bounds. No additional elliptic-L GRH or general AHC.','newly proved formulation in this run; no assertion of literature novelty','elliptic_reductions.tex/section.tex NT-E05 complete proof. NT-H02 gives h_k≫sqrt(d_k)/loglog(e^e d_k); d_k≤4x and ordered distinct discriminants give Σh_k^(−3/5)≪(loglogx)^(3/5)|D|^(7/10). Both branches of NT-E04 summation are solved; remainder branch x^(1/2)/log^4x dominates target. Compare ZywinaCor1.4p2/proofp15, whose weaker h estimate gives log^(10/7).','GRH_NIGHT/number_theory; diversity of Frobenius endomorphism fields of closed fibres of an elliptic scheme. No prime-order reduction, prescribed-point generation or Koblitz consequence.')


add('NT-R05','For any fixed finite Galois L/K and any real class function t, E_t(y)=y e^(−y/2)(π_t(e^y)−avg(t)Li_2(e^y)) has a B² expansion b_t−2ReΣ_{γ>0}a_t(1/2+iγ)e^(iγy)/(1/2+iγ), where b_t=−avg_g t(g²)−2a_t(1/2). The explicit coefficients a_t are weighted orders of cyclic-subextension Hecke functions, with all coincident zeros and multiplicities retained.','Precisely RH ζ_L; M suffices, and A suffices if L/Q is abelian. Finite-order Hecke holomorphy in the cyclic reductions is known. No nonabelian Artin holomorphy, linear independence, simplicity, or normality over Q required.','classical B² theorem with complete exact-input and coefficient-normalization audit','frobenius_laws.tex/section.tex NT-R05. Fiorilli–Jouve arXiv2001.05428v2 Prop3.18pp32–34, cyclic Lemmata3.14–3.15p30, Cor3.17pp31–32. Original Prop page rendered. Full cyclic reduction and Σ|a|²/(1/4+γ²)<∞ written here; analytic almost-periodic approximation remains cited classical input.','GRH_NIGHT/number_theory; trace statistics of finite-monodromy local systems on arithmetic curves, with cyclic finite étale induction. Constants are for the fixed field and class function.')
add('NT-R06','Any finite vector of the NT-R05 real Frobenius errors has a joint limiting law with mean vector b_j and covariance Σ_jk=2ReΣ_{γ>0}a_j(1/2+iγ)conj(a_k(1/2+iγ))/(1/4+γ²), absolutely convergent. A direction has zero variance exactly when all its noncentral spectral coefficients vanish.','RH ζ_L and NT-R05 only; no linear independence of zero ordinates or Artin holomorphy.','complete joint-law and covariance deduction proved here; no claim of literature novelty','frobenius_laws.tex/section.tex NT-R06. Closure of the one-parameter rotation in a countable torus, character averages and Stone–Weierstrass give finite-polynomial laws. L² convergence on Haar space plus B² approximation gives the full joint law and exact covariance.','GRH_NIGHT/number_theory; simultaneous Frobenius trace statistics of a finite collection of finite-monodromy objects. Rational relations among ordinates are retained, so neither independent coordinates nor Gaussian laws are inferred.')
add('NT-R07','For a nonempty finite étale X→U⊂Spec O_K with r generic components and splitting field L/K, set Π_X(x)=Σ_{p∈U,Np≤x}#X(k_p). Under RH ζ_L its normalized error around rLi_2 has mean −B_X with B_X=q_t+2Σ_i ord_(1/2)ζ_(K_i)≥r and finite variance V_X. The lower logarithmic density of Π_X(x)<rLi_2(x) is at least B_X²/(B_X²+V_X)>0.','RH ζ_L and NT-R05/06; M suffices, A for abelian L/Q. No simplicity, zero independence, generic Artin holomorphy or existence of a sign density is assumed.','complete permutation-character and one-sided lower-density proof written here','frobenius_laws.tex/section.tex NT-R07. Burnside gives avg(t)=r; full Artin permutation factorization gives the nonnegative central-order sum; counting g²∈H_i gives q_t≥r; finite boundary removal has zero B² effect. Markov optimization and Portmanteau give the exact lower-density fraction.','GRH_NIGHT/number_theory; H0 of finite étale arithmetic covers and point counts of closed fibres. This proves a positive lower logarithmic density, not a density greater than1/2 or the existence of every strict ordering density.')

add('NT-R08','For every nonempty finite étale X over an arithmetic open with r generic components and Galois splitting field L/K, RH ζ_L gives V_X≤C r²log²(Δ_L+2) and lower logarithmic density of Π_X(x)<rLi_2(x) at least1/(1+C log²(Δ_L+2)), for one absolute C. The bound is independent of the permutation rank; no uniform rate of convergence to the law is asserted.','Precisely RH ζ_L, NT-R05–07, unconditional uniform Dedekind zero count GM AppendixA ThmA.1, and Minkowski. M suffices; A if L/Q abelian. No bounded zero multiplicity or spacing assumption.','complete discriminant-uniform consequence proved here; independently whole-proof checked','frobenius_uniform.tex/section.tex NT-R08. Exact |a_t(ρ)|≤r ordρζ_L; uniform unit-interval count and squared-multiplicity summation; elementary AMGM plus Minkowski removes n. GM authorp26; Milne ANT v3.08 Thm4.3printed70 and Thm4.9proof72. Comparison FJ Prop4.6(87)p40/proofp41 uses squared L1 norm.','GRH_NIGHT/number_theory; uniform lower-frequency statement for H0 permutation traces of finite étale arithmetic covers, with splitting-field discriminant retained. No explicit numeric C or uniform x threshold claimed.')

add('NT-E06','For a CM elliptic curve E/k with all endomorphisms over k, every angle arc J and normalized-trace interval I satisfy counts |J|Li_2(x) and μ_CM(I)Li_2(x), respectively, with O_E,k(√x log²(2x)) error uniformly in all interval widths and endpoint conventions; μ_CM(dt)=dt/(π√(4−t²)). Intervals may depend on x.','Precisely RH L_k(s,η^m) for every integral power of the associated unitary CM Hecke character, including m0=ζ_k. M supplies this family; A alone does not supply nonzero infinity types. Entire continuation and boundary nonvanishing of nonzero powers are classical.','complete uniform-interval specialization proved here; classical analytic input precisely cited; whole author and root proof readings passed','cm_prime_angles.tex/section.tex NT-E06. BFK Prop2.5(2.3) printed1720/authorp6 and CM input footnote2 printed1740/authorp20; Erdős–Turán1948I TheoremIII printed374 (original image read). Uniform harmonic sum at H=ceil x, endpoint limits and two-arc trace preimage fully proved.','GRH_NIGHT/number_theory; rank-two H1 local system of an elliptic scheme splits over the CM field into conjugate rank-one characters; normalized Frobenius lies in the CM monodromy torus. Constants fixed E,k, no numerical/conductor-uniform assertion.')
add('NT-E07','Under NT-E06, any normalized-trace interval of CM measure μ>0 contains t_p for a good prime ideal with Np≤C_E,k μ^−2 log^6(e/μ). The same bound holds for an angle arc of length μ.','The exact Hecke-power RH family of NT-E06; no extra conjecture.','complete least-prime formulation proved here; no literature-novelty claim; independently whole-proof checked','cm_prime_angles.tex/section.tex NT-E07. Li_2(x)≥x/(2logx), x=C μ^−2log^6(e/μ), and explicit inequality sqrt C>2A_E,k(log(2C)+8)^3 give a positive count.','GRH_NIGHT/number_theory; one closed arithmetic fibre detects any prescribed positive-measure region of the CM torus. Constant depends on E,k; numerical constant not asserted.')
add('NT-E08','For any potential-CM elliptic curve E/k, F=kK with K its imaginary quadratic CM field and d=[F:k]∈{1,2}, each count a_p=±floor(2√Np) equals (πd)^−1∫₂ˣt^−1/4 dt/logt+O_E,k(x^5/8 log²(2x)), hence is asymptotic to 4/(3πd) x^3/4/logx.','Only RH for all integral powers of the unitary CM Hecke character of E_F, including ζ_F; M suffices. No non-CM elliptic GRH or Artin holomorphy asserted.','complete moving-threshold and quadratic-descent formulation proved here; no literature-novelty claim; independently whole-proof checked','cm_prime_angles.tex/section.tex NT-E08. Exact strict floor interval even at square norms; arcsine endpoint integral; geometric mesh h=x^−1/8 and summed uniform errors; norm-square O(√x) descent. Comparison BFK Prop4.9/Cor4.10pp1741–1742 and James–Pollack2017Thm1 authorp2 plus separate erratum; neither comparison proof supplies our new error bound.','GRH_NIGHT/number_theory; extremal Frobenius trace on H1 of CM elliptic arithmetic fibres. Split CM eigenspaces force zero trace on the nonsplit quadratic coset, giving exactly the factor1/d. Complete proof and review logs retained.')

add('NT-E09','For a potential-CM elliptic E/k, d=[kK:k], fixed c>0 and −1/2<λ<1/2, each count 0≤2√Np∓a_p<c(Np)^λ equals d^−1∫_(u0)^x g_c,λ(t)dt/logt+O_E,k,c,λ(x^(5/8+λ/4)log²(2x)), where g=π^−1 arccos(1−(c/2)t^(λ−1/2)) and u0=max(2,c^(1/(1/2−λ))). It is asymptotic to sqrt(c)/(πd(3/4+λ/2)) x^(3/4+λ/2)/logx. Same result for absolute-degree-one primes; λ<0 gives deficits tending to zero.','Precisely the CM Hecke-power RH family over kK from NT-E06/08; M suffices. Parameters E,k,c,λ fixed; no uniform endpoint constant and no λ=−1/2 assertion.','complete parameterized moving-target formulation proved here; whole author reading passed; no literature-priority claim','cm_shrinking_deficits.tex/section.tex NT-E09. Exact arcsine mass retained; explicit −u g′/g≤2α/sqrt3 with α=1/4−λ/2; mesh h=x^(−1/4+α/2); geometric error and Riemann bounds balance at x^(3/4−α/2). Quadratic descent and degree≥2 removal cost O(√x), below the error throughout the exact open range.','GRH_NIGHT/number_theory; closed arithmetic fibres whose H1 Frobenius lies in a shrinking scalar-neighbourhood of the CM torus, measured using the actual integer trace. Exact integral avoids a Taylor remainder that can exceed the power error when λ>3/10.')

add('NT-A04','For a fixed unitary Hecke η over K that is not finite order times a unitary norm power, all angle arcs J have count |J|Li_2(x)+O_K,η(√x log²(2x)), uniformly in widths/endpoints. Exact value fibers η(p)=z have O_K,η(√x log²(2x)) points. Infinite order alone is insufficient: if η(p)=χ(p)(Np)^it, χ has order h and t≠0, its hth prime Fourier moment equals x^(iht)/(1+iht)+o(1).','Precisely RH for positive powers L_K(s,η^m) and ζ_K; M supplies them. General-angle result excludes every finite-order norm twist; fixed-character constants and threshold only.','classical discrepancy theorem with exact input audit; complete singleton and norm-twist obstruction deductions proved here','hecke_shrinking_angles.tex/section.tex NT-A04. Rajan1998Prop4printed289–290 with Theorem1p286 character restriction and §1pp281–282 conventions. NT-C02 changes π_K to Li_2. Shrinking arcs give singleton bound; Abel summation and one integration by parts prove the nonzero Fourier-moment counterexample. Entire author proof reading passed.','GRH_NIGHT/number_theory; rank-one idele-class characters, with tensor-power CM-motive interpretation only for algebraic Hecke normalizations. No assertion that every unitary infinity type has an algebraic or étale realization.')
add('NT-A05','For η as NT-A04, fixed c>0 and0<α<1/2, let u0=max(2,c^(1/α)). Prime angles in the arc centered at θ of length c(Np)^−α, for u0<Np≤x, number c∫_(u0)^x u^−α du/logu+O_K,η,c,α(x^(3/4−α/2)log²(2x)), asymptotic to c/(1−α) x^(1−α)/logx. Error constant is uniform in the center.','The exact non-finite-order-mod-norm Hecke character and RH power family of NT-A04, including ζ_K. M suffices; no α=1/2 claim or uniform endpoint parameter constant.','complete shrinking-arc formulation proved here; whole author reading passed; no literature-priority claim','hecke_shrinking_angles.tex/section.tex NT-A05. Nested arcs and a geometric partition h=x^(−1/4+α/2) give summed error √x/h log²x and main bracketing error h x^(1−α). Exact common exponent and main-term dominance are proved.','GRH_NIGHT/number_theory; shrinking neighborhoods in the compact rank-one Hecke torus, with conditional arithmetic prime counting. No random-zero or independence assertion.')

add('NT-E10','For a potential-CM elliptic E/k with CM field K and D=|disc K|, degree-one good primes q=p outside ramification of kK/k satisfy the endpoint event0≤2√p∓a_p<c/√p, p>c/2, only on the split coset. There 4p−a_p²=Db² with nonzero integer b; for all sufficiently large p the event is equivalent to the chosen sign a=±a_p>0 and0<Db²<4c. EqualityDb²=4c never qualifies. If4c≤D only finitely many such primes exist; unramified exceptions must have p≤c/2.','Unconditional: CM endomorphism field kK, good-reduction specialization and faithful Tate-module action, Hasse/Frobenius characteristic polynomial. Neither A nor M is required.','complete endpoint and finite norm-form reduction proved here; whole author and root proof readings passed','cm_endpoint_gate.tex/section.tex NT-E10. Centralizer of specialized K in the Tate-module endomorphism algebra gives Frobenius in O_K; exact δsqrtp=B/(2+a/sqrtp) and B<4c−c²/p give p>max(c/2,c²/(4c−Bmax)). Nonsplit trace0 and strict equality exclusion complete the proof.','GRH_NIGHT/number_theory; integral CM torus lattice O_K with bounded transverse coordinate b at the square-root endpoint. Remaining p=(a²+Db²)/4 retain parity and curve-specific Frobenius conditions; no unrestricted converse or quadratic-prime infinitude inferred. Root suggested the endpoint route.')

add('NT-A06','For Gaussian prime ideal angles moduloπ/2, 3≤K≤X≤K² and X large, the normalized measure of centers whose arc of lengthπ/(2K) contains no prime ideal of norm in(X/2,X) is O(Klog²K/X). Requiring absolute degree one gives O(Klog²K/X+1/K).','Precisely RH for L(s,Xi_m), Xi_m((α))=(α/conjα)^(2m), m≥1. M supplies it; the mean uses unconditional prime ideal PNT. No LI, simplicity or conjectural variance asymptotic.','classical variance premise with complete exact-input and exceptional-measure deduction proved here','gaussian_almost_sure_angles.tex/section.tex NT-A06. Rudnick–Waxman arXiv1705.07498v2 Thm3.2authorp12, proof§4.4p20, Lemma3.1pp11–12; sourceS-NT-RW. Support, uniform mean factor1/K, Chebyshev and inert-angle exclusion proved in full.','GRH_NIGHT/number_theory; closed points of SpecZ[i] and characters of its compact CM torus, with Haar averaging over angular centers. No finite-field purity transfer is asserted.')
add('NT-A07','For every fixed ε>0 and almost every Gaussian angular centerθ, every sufficiently large real K has a degree-one prime ideal in the centered arc of lengthπ/(2K), with norm≤2^(5+ε)K(logK)^3(loglogK)^(1+ε). The threshold may depend onθ,ε; infinitely many distinct prime ideals occur.','Exactly the nonzero Gaussian angular Hecke RH family in NT-A06, hence M; first Borel–Cantelli requires no independence.','complete almost-sure all-scales formulation proved here; whole author reading passed; no priority claim','gaussian_almost_sure_angles.tex/section.tex NT-A07. Dyadic K_j=2^j, X_j=K_jlog³K_j(loglogK_j)^(1+ε) give summable exceptional probabilities O(1/[j(logj)^(1+ε)]+2^−j); nested arcs interpolate all realK. Norms>X_j/2 imply infinitely many primes.','GRH_NIGHT/number_theory; almost every shrinking neighborhood system in the Gaussian CM torus. The elementary zero-angle gap is included to distinguish almost every fixed center from uniformity over all centers.')

add('NT-A08','For any primitive unitary Hecke character λ over degree-n K that is not a pure unitary norm character, RH L(s,λ) gives |Σ_(Na≤x)Λ_K(a)λ(a)|≪√x log(2x)[log C(λ)+n log(2x)], with an absolute constant and C(λ)=|D_K|Nf_λ∏(3+|κ_λ,j|). Consequently its prime sum outside any f divisible by f_λ is ≪√x[log C(λ)+n log(2x)]+log Nf. The principal case has main Li_2(x) and is treated separately.','Precisely RH for this primitive Hecke L-function; M suffices. Classical entire continuation, finite order, boundary nonvanishing and the IK degree/conductor-uniform explicit-formula theorem. Arbitrary unitary infinity types allowed.','complete uniform complex-coefficient reduction proved here; whole author and root proof readings passed','ray_class_angles.tex/section.tex NT-A08. Iwaniec–Kowalski Theorem5.15(5.56) printed114 and §5.1pp93–95 give the real-or-conjugate-paired gamma premise. Pair L(s+it,λ)L(s−it,barλ), then two explicitly bounded Abel steps with fixed t recover the imaginary part without an extra logarithm; prime powers and finite exclusions fully checked.','GRH_NIGHT/number_theory; rank-one idele-class characters and their conjugate realification. Only normalized algebraic types are identified with CM motives; no pure-norm shifted-pole argument is used.')
add('NT-A09','For a ray class group G of order h, unitary η not finite order times a unitary norm power, f=lcm(m0,fη), Q=|D_K|Nf(4+max|κη,j|)^n and L(x)=log Q+2n log(3x), the number of primes outside f in any class a and any angular arc J is |J|Li_2(x)/h+O(√x log(2x)L(x)). Constant is absolute and uniform in field, character, ray modulus, class, width and endpoints; same bound for absolute-degree-one primes. There is no factor h in the error.','Exactly RH for the primitive functions attached to χη^m, χ∈Ghat and m≥0; M supplies them. The m=0 principal term uses RH ζ_K. The finite-order-times-norm exclusion prevents any m>0 pure-norm factor.','complete simultaneous finite-class/angle formulation proved here; whole author and root proof readings passed','ray_class_angles.tex/section.tex NT-A09. NT-A08, explicit conductor bound C(χη^m)≤Q(m+1)^n, character orthogonality with cancellation of h, and Erdős–Turán at H=ceil x. Singleton limits and degree≥2 deletion are included. Classical sources S-NT-IK and S-NT-ET.','GRH_NIGHT/number_theory; joint Frobenius condition in a finite ray-class cover and compact rank-one Hecke torus; character algebra Ghat×Z. Finite mass1/h and analytic conductor retained separately.')
add('NT-A10','With NT-A09 data, fixed c>0,0<α<1/2 and u0=max(2,c^(1/α)), count primes u0<Np≤x in ray class a and the fixed-center arc of length c(Np)^−α. The count equals (c/h)∫_(u0)^x u^−α du/logu+O_c,α(√x log(2x)L(x)+h^−1/2 x^(3/4−α/2)√L(x)). It is asymptotic to c x^(1−α)/[h(1−α)logx] whenever h L(x)(logx)^2=o(x^(1/2−α)); same degree-one result.','Precisely the primitive Hecke family of NT-A09; M suffices. Parameters c,α fixed; all other dependence is explicit in h,L(x). No α=1/2 assertion.','complete optimized shrinking-arc formulation proved here; whole author and root proof readings passed','ray_class_angles.tex/section.tex NT-A10. Geometric mesh δ gives error A/δ+Bδ with A=√x log(2x)L(x), B=(c/h)x^(1−α)/logx; δ=min(1/2,√(A/B)) yields A+√(AB). Both relative-error limits and the initial-segment convention are proved.','GRH_NIGHT/number_theory; shrinking torus neighborhoods with a simultaneously prescribed finite étale Frobenius fiber. The improved h^−1/2 balancing term comes from retaining the finite-class mass in the mesh.')
add('NT-A11','With NT-A09 data, any ray class and any arc of positive length μ contain a degree-one prime outside f of norm≤C(h/μ)^2 V^6, where V=log(eQ)+n log(e n h/μ) and C is absolute. No numerical value of C is claimed.','Exactly the primitive Hecke family in NT-A09, supplied by M; no independent Artin-holomorphy or zero-spacing assumption.','complete least-prime formulation with uniform parameters proved here; whole author and root proof readings passed','ray_class_angles.tex/section.tex NT-A11. Set d=h/μ and x=C d²V⁶. Bounds n log V≤2V, log x≤(log C+14)V/n and L(x)≤(32+2log C)V reduce positivity to an explicit cubic-log inequality dominated by √C.','GRH_NIGHT/number_theory; one absolute-degree-one arithmetic point detects a joint ray-class/torus region, with finite conductor, discriminant and infinity type controlled explicitly.')

add('NT-C09','For degree n≥2 and D=|disc K|, the ordinary class group is generated by prime ideals of norm≤(4−1/(2n)+1/(2n²))log²D. The correction1/(2n²) can be omitted for n≥5, or for n2/3/4 when logD≤63/353/833 respectively or logD≥12184/18455/27911 respectively. Middle intervals are unasserted ranges, not actual counterexample lists.','RH ζ_Q and RH for all ordinary ideal-class Hecke characters of K, including ζ_K; equivalently RH ζ_Q and RH ζ_HK for the ordinary Hilbert class field. M suffices; A if H_K/Q is abelian, not merely if K/Q is abelian.','precise published theorem and input reduction; numerical source computations credited and not rerun','Grenié–Molteni2025 Theorems1–2 authorp2/Table1; complete §4 proofpp10–12, analytic interface§2pp3–5 and Proposition1pp8–9. Small-discriminant premise GM2018 Theorem3.5(3.10)p6. class_generators.tex/section.tex NT-C09. Original p2 image inspected.','GRH_NIGHT/number_theory; Pic(Spec O_K) and the ordinary unramified abelian class-field cover. Strengthens carried NT-C05 without claiming fresh access to Bach1990 original.')
add('NT-C10','With the NT-C09 analytic input, primes of norm≤(4−2/(3n)+3/(8n²))log²D generate a subgroup containing Cl(K)². If the class number is odd, they generate all Cl(K). Correction3/(8n²) can be omitted for n≥5, or n2/3/4 with logD≤65/379/993 or logD≥7968/9832/13108 respectively.','Exactly the RH family in NT-C09; M supplies it. Odd class number is an additional premise only for the full-group conclusion at this smaller bound.','precise published theorem with subgroup-containment clarified from its proof; full input and elementary odd-order transfer checked','Grenié–Molteni2025 Theorems3–4 authorpp2–3/Table2; §5completeproofpp12–13. The opening §5 proves containment of Cl²; it does not claim each selected prime class itself belongs to Cl². class_generators.tex/section.tex NT-C10.','GRH_NIGHT/number_theory; the class-field quotient remaining after these closed-point Frobenius generators has exponent at most two. No odd-class-number testing algorithm inferred.')
add('NT-C11','For any subgroup H≤Cl(K), nonnegative even compact test F with nonnegative Fourier transform gives a finite generation certificate for Cl(K)/H after omitting any prime set E: 2Σ_p(−1)^1_E(p) logNp Σ_m F(m logNp)/(Np)^(m/2)>F(0)(logD−(γ+log8π)n)+nI(F)−r1J(F) forces the nonomitted primes Np<e^L together with H to generate Cl(K), where suppF⊂[−L,L], I=∫(F(0)−F)/(2sinh(x/2)), J=∫F/(2cosh(x/2)). The explicit triangular criterion C11.4 is included.','Only RH for nontrivial ordinary ideal-class characters trivial on H; no ζ_K or ζ_Q RH required. Classical Weil–Poitou explicit formula and the stated bounded-variation regularity. M supplies this family.','complete quotient/exclusion and triangular-constant proofs; author and root whole readings passed','class_generators.tex/section.tex NT-C11. Source Grenié–Molteni2025 Theorem5pp13–14/(3)p3; Belabas–Diaz y Diaz–Friedman Cor2.2pp6–7 and Thm2.1pp5–6. New proof chooses an annihilating quotient character and uses positivity; exact support and all prime powers retained.','GRH_NIGHT/number_theory; a finite closed-point certificate for Frobenius generation of an ordinary unramified abelian quotient. Certified numerical evaluation of a strict inequality is required for an actual computation; none was fabricated.')
add('NT-C12','Given an integral basis of the maximal order O_K and its full integer multiplication table, one can deterministically enumerate in polynomial input bit time a prime-ideal factor base generating Cl(K) under NT-C09, with norms≤B_n+2, B_n=(4−1/(2n)+1/(2n²))log²D. With a promised odd class number use B′_n+2 from NT-C10. Output consists of explicit integral lattice bases.','The supplied maximal-order representation and the analytic input of NT-C09. Finite-algebra enumeration itself is unconditional. No maximal-order computation, integer factorization, relation lattice, unit computation or class-group presentation is supplied by this statement.','complete bit-model enumeration proof; author, complexity and root whole readings passed; no priority claim','class_generators.tex/section.tex NT-C12. Trace-matrix/Hadamard bounds log₂D≤2bn+(5n/2)log₂n; certified logarithmic rounding avoids integer-separation assumptions. For each small p use nilradical ker Frob^e, p^e≥n, reduced fixed algebra F_p^g, simultaneous eigenspaces, then explicit RREF preimage lattice bases.','GRH_NIGHT/number_theory; effective enumeration of closed points of Spec O_K from the actual integral algebra, with at most nT outputs. Complexity and root independently read the complete written enumeration proof and reported passes.')
add('NT-C13','Under NT-C09, an abelian E/K unramified at all finite places and split at every real place is trivial if all primes Np≤B_n split completely. If all primes Np≤B′_n split, Gal(E/K) has exponent at most two. The correction-free ranges of NT-C09/C10 have the same conclusions.','Precisely the NT-C09 RH family plus ordinary global class field theory; M suffices. Real-place splitting is retained, so this is an ordinary, not narrow, class-field assertion.','complete short Frobenius quotient consequence; author and root whole readings passed','class_generators.tex/section.tex NT-C13. Artin reciprocity sends the small prime classes to Frobenius; killing G(B_n)=G gives trivial quotient, while killing G(B′_n)⊇G² gives a quotient of G/G². Milne CFT V3.5–3.6 cited earlier.','GRH_NIGHT/number_theory; finite recognition of ordinary abelian étale covers and the remaining elementary2 quotient. No nonabelian fundamental-group generation asserted.')

add('NT-A12','Let L/K be finite Galois, C a conjugacy class, g∈C, H=<g>, h=|H|, F=L^H, δ=|C|/|G|, and η unitary over K not finite order times a norm power. Put ν=η∘N_F/K, s_F the radical above a finite omitted set S containing ramification and η-conductor primes, Bν=4+max|κν,j|, Q_C=D_L(N_F fν N_F s_F)^h Bν^[L:Q], L_C(x)=logQ_C+2[L:Q]log(3x). Primes outside S in C and any angle arc J number δ|J|Li_2(x)+O_abs(δ√x log(2x)L_C(x)); same for absolute-degree-one primes.','Exactly RH for primitive L_F(s,χν^m), χ∈Hhat and m≥0, including ζ_F. M supplies this rank-one family. No general Artin holomorphy. Finite extension norm pullback preserves the non-finite-order-mod-norm premise by the diagonal idele identity.','complete nonabelian class/angle formulation proved here; whole author and independent complexity proof readings passed','frobenius_hecke_angles.tex/section.tex NT-A12. Exact cyclic induction 1_C=δΣχ barχ(g)Ind_H^Gχ, conductor–discriminant average, NT-A08 complex Hecke estimate and ET discrepancy; every ramified or relative-degree≥2 deletion retained. Classical locators S-NT-IK5.15p114, S-NT-ETIII, S-NT-NEUKIRCH VII11.9p534/proof533–535.','GRH_NIGHT/number_theory; finite étale G-cover coupled to a compact Hecke torus through the cyclic intermediate cover Spec O_F. Algebraic-motive interpretation only for normalized algebraic Hecke types; no priority claim.')
add('NT-A13','With NT-A12 data, c>0,0<α<1/2,u0=max(2,c^(1/α)), count u0<Np≤x, Frobenius C and a fixed-center arc of length c(Np)^−α. The count is δc∫_(u0)^x u^−α du/logu+O_c,α(δ√x log(2x)L_C(x)+δx^(3/4−α/2)√L_C(x)). Uniform relative asymptotic holds if L_C(x)(logx)^2=o(x^(1/2−α)); same degree-one statement.','Precisely the cyclic rank-one RH family in NT-A12, supplied by M. Fixed c,α; other degree/conductor/density parameters explicit. No endpoint α=1/2 claim.','complete shrinking-target formulation proved here; whole author and independent complexity proof readings passed','frobenius_hecke_angles.tex/section.tex NT-A13. Nested arcs and geometric partition give A/epsilon+B epsilon with both A and B carrying δ; optimal epsilon gives A+sqrt(AB), retaining the density in each error.','GRH_NIGHT/number_theory; shrinking torus neighborhoods inside a specified nonabelian Frobenius class. Relative error loses no extra inverse-density factor; the field dependence remains in D_L and [L:Q].')
add('NT-A14','With NT-A12 data, every arc of length μ>0 contains the η-angle of an absolute-degree-one prime outside S with Frobenius C and norm≤C0 μ^−2 V_C^6, V_C=log(eQ_C)+[L:Q]log(e[L:Q]/μ). C0 is absolute; no numerical value claimed.','Exactly NT-A12 cyclic Hecke RH family; M suffices. The prescribed finite cover may be nonabelian.','complete uniform least-prime consequence proved here; whole author and independent complexity proof readings passed','frobenius_hecke_angles.tex/section.tex NT-A14. Explicit bounds for logx, log(2x), L_C and n_L logV_C reduce positivity to sqrt(C0)>2A0(logC0+14)(logC0+15)(32+2logC0). Common δ cancels.','GRH_NIGHT/number_theory; an arithmetic closed point realizes a simultaneous finite étale conjugacy condition and positive-volume rank-one torus region.')
add('NT-E11','For an elliptic E/K with all CM defined over K, any finite Galois L/K and conjugacy class C, impose0≤2sqrt(Np)∓a_p<c(Np)^λ, −1/2<λ<1/2. Outside S and for u0<Np≤x, its count is δ∫_(u0)^x w(u)du/logu+O_c,λ(δ√x log(2x)L_C(x)+δx^(5/8+λ/4)√L_C(x)), w=π^−1 arccos(1−(c/2)u^(λ−1/2)), with u0=max(2,c^(1/(1/2−λ))). Same degree-one formula. In particular each extremal trace a_p=±floor(2sqrt(Np)) has count (δ/π)∫_2^x u^−1/4 du/logu+O_fixed(x^(5/8)√log(2x)), asymptotic4δ/(3π)x^3/4/logx.','The normalized CM character η and exactly the cyclic twisted family in NT-A12 for this η; M supplies it. S includes bad reduction, ramification and conductor primes. All CM defined over K is retained; no unproved potential-CM descent or non-CM standard L-function GRH.','complete simultaneous CM/Frobenius formulation proved here; whole author and independent complexity proof readings passed','cm_frobenius_deficits.tex/section.tex NT-E11. Exact deficit arcs and logarithmic derivative ≤2α/sqrt3, optimized NT-A12 geometric mesh, strict floor equivalence including square norms, and fixed-data error comparison. Classical CM premise NT-E06/S-NT-BFK.','GRH_NIGHT/number_theory; Frobenius on a CM rank-two local system constrained simultaneously in an arbitrary finite étale cover, including a division-field cover from another curve. The lambda=-1/2 finite norm-form gate remains; no Koblitz or general non-CM automorphy inference.')

add('NT-A15','For r unitary Hecke coordinates η_i with every nonzero monomial outside finite-order times norm characters, impose Frobenius C in finite Galois L/K. With the explicit norm-pulled-back conductor Q_* of A15.2 and L_*(x)=logQ_*+2[L:Q]log(3x), any product of arcs of volume μ contains δμLi_2(x)+O_r(δ√x(log(2x))^r L_*(x)) primes outside S; same absolute-degree-one bound. If μ>0 a prime exists with norm≤C_r μ^−2 V_*^(2r+4), V_*=log(eQ_*)+[L:Q]log(e[L:Q]/μ).','Exactly RH for primitive L_F(s,χ∏ν_i^m_i), χ∈<g>hat, m∈Z^r, F=L^<g>, ν_i=η_i∘N_F/K. M supplies it. The mixed tensor products and full monomial non-finite/norm condition are explicit; no general Artin holomorphy.','complete multidimensional arithmetic formulation proved here; whole author and root readings passed','joint_hecke_tori.tex/section.tex NT-A15. Conductor bound and exact cyclic induction extend NT-A12; Dick–Pillichshammer authorThm3.26printed/PDF84 gives ETK, with proof reference Drmota–Tichy§1.2.2. Weighted frequency sum=(1+2Σ1/j)^r−1, faces, empty list, degree-one loss and explicit C_r logarithmic inequalities all proved.','GRH_NIGHT/number_theory; a finite étale G-cover coupled to a compact Hecke torus of rank r. Only normalized algebraic Hecke types receive a CM tensor-category interpretation. No priority claim.')
add('NT-A16','With NT-A15 data, fixed c_i>0,α_i>0, A=Σα_i<1/2 and u0=max(2,max_i c_i^(1/α_i)), shrinking fixed-center boxes of side c_i(Np)^−α_i, for u0<Np≤x in class C, have count δ(∏c_i)∫_(u0)^x u^−A du/logu+O(δ√x log^r(2x)L_*(x)+δx^(3/4−A/2)log^((r−1)/2)(2x)√L_*(x)). Constant depends only on r,c_i,α_i. Relative asymptotic holds if L_*(x)(logx)^(r+1)=o(x^(1/2−A)); same degree-one version.','Precisely the mixed cyclic rank-one RH family and independence premise of NT-A15, hence M. Total shrinking exponent A<1/2 is essential to the proved asymptotic; no boundary assertion.','complete optimized shrinking-box formulation proved here; whole author and root readings passed','joint_hecke_tori.tex/section.tex NT-A16. Nested boxes and multiplicative mesh give A0/epsilon+B0epsilon with A0=δ√x log^r x L_* and B0=δ(∏c_i)x^(1−A)/logx; optimization proves the exact log powers and both relative limits.','GRH_NIGHT/number_theory; simultaneously shrinking neighborhoods in several compact Hecke torus coordinates with a prescribed finite Frobenius class. The sum of exponents, not each exponent separately, controls the proved range.')
add('NT-A17','Under M, the joint angles of finitely many fixed unitary Hecke η_i on primes in any fixed nonempty Frobenius class are Haar equidistributed on the full r-torus iff every nonzero monomial is not finite order times a norm power. If a monomial equals θ times norm with θ^b=1, its bth-power normalized prime Fourier moment is x^(iτ)/(1+iτ)+o(1), with ideal norm exponent τ; its modulus tends to1/sqrt(1+τ²), and it is exactly1 whenτ0.','M suffices for the mixed-family sufficiency. Necessity uses only fixed-field Chebotarev PNT (here supplied by RHζ_L) plus the actual finite-order/norm relation. Separate coordinate infinite order/equidistribution is insufficient.','complete necessary-and-sufficient full-torus criterion proved here; whole author and root readings passed','joint_hecke_tori.tex/section.tex NT-A17. Sufficiency follows from A15 boxes; necessity raises away the finite character, applies Abel summation to N_C(x), evaluates ∫u^(iτ)/logu, and compares a nonzero Fourier character with Haar measure.','GRH_NIGHT/number_theory; the character lattice detects proper torus relations and radial norm drift. No statistical independence of zeros is claimed.')
add('NT-E12','For two elliptic curves over K with all CM defined over K and distinct imaginary quadratic CM fields, any common good prime with a_1²=a_2² must have square norm q and a_1²=a_2²=4q. Hence no absolute-degree-one prime has equal absolute traces; simultaneous |a_i|=floor(2sqrtq) can occur only at square norms and exact Hasse endpoints. There are at most [K:Q]sqrtx such prime ideals of norm≤x.','Unconditional good-reduction specialization, faithful auxiliary Tate-module action and the Frobenius characteristic polynomial. Neither A nor M; all CM defined over K is retained.','complete integral endpoint obstruction proved here; whole author and root readings passed','cm_joint_endpoint_obstruction.tex/section.tex NT-E12. BFK Remark4.11 published1743/author22 already gives the rational positive-extreme special case and credits Sutherland; our full broader proof follows. The centralizer of M⊗Q_l in a faithful two-dimensional Tate module is itself, so Frobenius lies in M. Nonrational Frobenius generates Q(sqrt(a²−4q)); equal squared traces would identify the two CM fields. Rational Frobenius forces exact Hasse equality and square norm.','GRH_NIGHT/number_theory; two distinct quadratic endomorphism algebras cannot have the same noncentral Frobenius characteristic polynomial. This is an actual arithmetic obstruction at the two-extremal-coordinate total shrinking exponent1/2, compatible with fixed-box Haar equidistribution; persists under any further finite Frobenius restriction.')

add('NT-E13','For elliptic E_1,E_2 over k with distinct potential-CM fields M_i, let F=kM_1M_2 and omit bad reduction and ramification in F/k. If a_1²=a_2²≠0 at a remaining prime, that prime splits completely in F/k, its norm q is square, and a_i²=4q. Thus simultaneous |a_i|=floor(2sqrtq) is impossible at degree-one primes, and occurs at at most [k:Q]sqrtx prime ideals of norm≤x. Explicitly y²=x³−x and y²=x³+1 never both attain the integer absolute Hasse extreme at any rational prime p>3.','Unconditional exact CM endomorphism field kM_i, good-reduction Tate representation, and NT-E12 centralizer theorem. No all-CM-defined-over-k assumption, A, M or Artin holomorphy. The nonzero trace condition excludes the genuinely possible common trace-zero nonsplit case.','complete descent and explicit arithmetic counterexample proved here; whole author and root proof readings passed','potential_cm_joint_endpoint.tex/section.tex NT-E13; earlier rational positive-extreme special case BFK Remark4.11p1743, attributed to Sutherland. Faithful characteristic-zero tangent action identifies the endomorphism field; a nonsplit Frobenius swaps CM eigenlines and has trace0. Nonzero traces force both quadratic fields split, so norm-preserving lift to the compositum permits NT-E12. Explicit automorphisms and discriminants64,−432 verify the two Q-curves.','GRH_NIGHT/number_theory; component-group action on CM eigenlines followed by the quadratic endomorphism-algebra obstruction. This exhibits an actual rational-prime failure of simultaneous integral endpoint counting at the two-coordinate shrinking boundary, while preserving all fixed-box distribution results.')

add('NT-A18','For fixed unitary Hecke coordinates η_i and a fixed nonempty Frobenius class C in L/K, suppose every nonzero monomial has infinite order. Then Σ_(p∈C,Np≤x)1/Np=δ loglogx+B_C+O(log(2x)/sqrtx), while every nonzero mixed harmonic sum Ση(p)^m/Np converges to B_m with tail O_m(1/logx+log(2x)/sqrtx); drop1/logx when no induced factor is pure norm. The normalized reciprocal-prime measures tend to full torus Haar measure, including degree-one primes and all box endpoints. Under M the infinite-order monomial condition is also necessary. The corresponding twisted Euler products converge locally uniformly to nonzero holomorphic limits for |z|<2.','Exactly RHζ_L and RH for every primitive non-pure-norm L_F(s,χ∏ν_i^m_i), χ∈<g>hat, m≠0, F=L^<g>, ν_i=η_i∘N_F/K. Pure norm factors use RHζ_F inherited from ζ_L. M supplies this family; no general Artin holomorphy. All data fixed, no frequency-uniformity near norm relations.','complete weighted torus/finite-limit formulation proved here; whole author and root proof readings passed','reciprocal_prime_tori.tex/section.tex NT-A18. Full Stieltjes calculation and explicit pure-norm tail2/(|τ|logx), cyclic induction, absolute higher-residue-degree correction, Mertens constant, Fourier approximation, finite-order obstruction and normal convergence of the logarithmic Euler product. Antecedents NT-A08/C02/C08/A12 with their cited classical inputs.','GRH_NIGHT/number_theory; reciprocal-norm measures on closed points in a finite étale Frobenius class, coupled to compact rank-one Hecke coordinates. This removes radial norm drift but not finite character relations. General unitary infinity types receive an idele-class interpretation; no joint-zero-statistics hypothesis or motivic realization claimed.')
add('NT-A19','Let χ_i be fixed primitive Dirichlet characters and let real t_i be rationally independent. In any fixed reduced progression p≡a modq, the points (χ_i(p)p^(it_i))_i, excluding conductor primes and weighted by1/p, tend to full torus Haar measure; every nonzero mixed prime harmonic sum converges to a finite constant. Ordinary equal prime weights fail: a suitable coordinate Fourier moment equals x^(ib_i t_i)/(1+ib_i t_i)+o(1), of nonzero limiting modulus.','Only RH for primitive Dirichlet L-functions with conductors dividing Q0=lcm(q,f_1,...,f_r), including ζ for conductor1. This is a finite subfamily of user-adopted A_D. No additional M input. Rational independence ensures all nonzero mixed norm frequencies are nonzero.','complete A_D-only specialization and ordinary-weight obstruction proved here; whole author and root proof readings passed','reciprocal_prime_tori.tex/section.tex NT-A19. Partition into reduced classes modQ0; use NT-P12 and the exact A18.6–A18.7 Stieltjes limit for each pure norm wave. Raise away each finite character to apply the NT-A17 ordinary Abel moment calculation.','GRH_NIGHT/number_theory; a finite cyclotomic Frobenius condition coupled to rationally independent radial unitary norm characters. Gives an explicit difference between ordinary and reciprocal-prime torus distribution, without claiming algebraic Hecke types or zero independence.')

add('NT-A20','For R=O_{K,S}, S finite containing all archimedean places and |S|≥2, an ideal class C is Euclidean in Lenstra’s sense iff Pic(R)=<C>, assuming RH for ζ_{K(ζ_m,(R×)^(1/m))} for all positive squarefree m. Thus a cyclic Picard group of order h_S has exactly φ(h_S) Euclidean ideal classes, and a noncyclic group has none. At most one can be norm-Euclidean, so if cyclic h_S>2 at least φ(h_S)−1 admit reduction without the norm reduction.','Exactly the stated unit-Kummer Dedekind RH family; M supplies it. Necessity and fixed-function uniqueness are unconditional. General A_D does not supply these potentially nonabelian Kummer fields.','precise classical sufficiency plus complete elementary reformulation/count; whole author and geometry proof readings passed','euclidean_ideal_classes.tex/section.tex NT-A20. Lenstra1979 Proposition2.2 printed127/PDF8 (≥2 visually checked) supplies sufficiency and refers to methods of Lenstra1977 rather than printing that analytic proof. Definition1.1p123, complete elementary Lemma1.5/Theorem1.6 and fixed-function uniquenesspp124–125 read; full minimal-counterexample and norm-uniqueness arguments written here.','GRH_NIGHT/number_theory; reduction in an invertible sheaf generating Pic(Spec O_{K,S}). Exact cyclicity and the squarefree Kummer field family retained. No new analytic sufficiency proof, norm algorithm, or runtime bound claimed.')
add('NT-A21','For every number field K with cyclic ordinary class group of order h, under M every generator class contains an absolute-degree-one prime p with Np≤[h(4log|discK|+2.5[K:Q])+5]^2 such that O_{K,S∞∪{p}} is Euclidean. This includes fields whose original unit group is finite. If p^h=(a), the ring is exactly O_K[1/a].','RHζ_HK and RHζ_Q for the bounded prime from C07, followed by the NT-A20 unit-Kummer RH family for the particular selected one-prime localization. M supplies both. The two class-field zeta functions are not asserted to imply the localization-dependent family.','complete bounded one-point localization consequence proved here; whole author and geometry proof readings passed','euclidean_ideal_classes.tex/section.tex NT-A21. NT-C07 gives the prime bound, including Q exception; full divisor proof identifies Pic of the localization with Cl(K)/<[p]>. |S∞∪{p}|≥2 permits A20; explicit fractional-ideal-to-element division formula proves Euclideanity, and p^h=(a) gives the affine principal-open realization.','GRH_NIGHT/number_theory; deleting one quantitatively bounded closed point kills the ordinary Picard group, and the unit-Kummer analytic input supplies Euclidean reduction. Cyclic class group remains a hypothesis; the norm bound is not a complexity bound for computing or executing the reduction.')

add('NT-E14','For non-CM elliptic curves E1,E2/Q with conductors N1,N2 and m=rad(2N1N2), non-Q-isogeny is detected by a common good odd prime p≤(482logm+2880)^2 with a_p(E1)≠a_p(E2). Equality at all such primes is equivalent to Q-isogeny.','Only RHζ_Q and RHζ_T for the actual field T=F(sqrtm), where F is the finite trace-detecting quotient of the joint2-adic division tower and [F:Q]≤192. A convenient finite sufficient family consists of all Galois T/Q of degree≤384 unramified outside m; M supplies it. No non-CM elliptic GL2 RH or general Artin holomorphy.','precise published theorem transfer; source proof and exact analytic reduction read; whole author/root/geometry readings passed','effective_elliptic_detection.tex/section.tex NT-E14. Mayle–Wang2024 Theorem2p1401, entire proofpp1408–1410, Proposition12pp1407–1408 and Corollary6pp1404–1405. Published Bach–Sorenson Table3 computations credited, not rerun. Milne ANT8.42–8.43pp151–152 gives finite-family qualification.','GRH_NIGHT/number_theory; finite Frobenius detection of semisimple rank-two Tate local systems, followed by Faltings to recover Q-isogeny. The finite quotient need not be the first2-division field; the non-CM hypothesis belongs to this precise published numerical theorem.')
add('NT-E15','For a non-CM elliptic E/Q of conductor N_E, every prime ell>964lograd(2N_E)+5760 has surjective mod-ell Galois image GL2(F_ell).','Only RHζ_Q and the NT-E14 trace-detection fields F_D(sqrtm) for the finitely many relevant quadratic twists E_D, with m=rad(2N_E), squarefree D dividing N_E with signs allowed. All fields have degree≤384 and are unramified outside m; M supplies them. Classical modular-curve exclusions, local inertia, twist nonisogeny and Faltings remain explicit inputs.','precise published theorem transfer with bounded-degree Dedekind RH family; whole author/root/geometry readings passed','effective_elliptic_detection.tex/section.tex NT-E15. Mayle–Wang2024 Theorem1p1401, complete §5.2 proofpp1412–1413 and Lemmas14–15pp1411–1412. The witness has nonzero trace divisible by ell; Hasse gives ell≤2sqrtp and doubles the E14 constants.','GRH_NIGHT/number_theory; effective maximal residual monodromy for H1 of a non-CM elliptic curve over Q. This neither establishes a uniform cutoff37 nor extends the statement to arbitrary base fields or CM curves.')
add('NT-E16','Given two nonsingular integral Weierstrass equations E1,E2/Q, including CM curves, let R=2|Delta1Delta2|, b=bitlength(R) and B=(1532b+10181)^2. Under M, Q-isogeny is equivalent to equality of point counts at every prime p≤B with p not dividing R. Direct O(B^3) aggregate modular enumeration gives a deterministic decision algorithm polynomial in the supplied coefficient bit length.','RHζ_Q and RHζ_T for Galois T/Q of degree≤384 unramified outside radR suffice; only one actual quotient field plus quadratic avoidance extension is used for a nonisogenous pair. Faltings Corollary2(i)⇔(iii)p361, NOS as MW Theorem8/Corollary9pp1406–1407, local different inequality MW Lemma7p1405, and NT-C03. M supplies precisely the analytic family; no conductor or integer factorization oracle.','complete finite-quotient and bit-model formulation proved here; whole author/root/geometry readings passed; no literature-priority claim','effective_elliptic_detection.tex/section.tex NT-E16. Full proof uses the unsaturated Z2-span A and its actual quotient A/2A, minimum-valuation trace functional, order≤255 and divisibility by36·2^(8j−8) giving degree≤192, ramification exclusion by sqrt(radR), discriminant bound383logm+384log384, and explicit1532/10181 cutoff. Complete bit analysis and direct point counting included.','GRH_NIGHT/number_theory; closed points of the good-reduction arithmetic open detect the Q-isogeny class of H1. A differing prime/count is an unconditional negative certificate; universal positive correctness uses the stated RH family. No isogeny construction, geometric-isogeny decision, endomorphism-ring algorithm, or non-CM promise is inferred.')

add('NT-E17','For monic irreducible H in Z[X] of degree h>=1, put b=bitlength(h+1), P=(72b+264)^2. Under quadratic Dirichlet RH, H is a Hilbert class polynomial iff H² divides Res_Y(H(Y),Phi_ell(X,Y)) for some prime5<=ell<=P. Exact scanning gives deterministic polynomial time in h times the padded logarithmic height. A positive divisibility certificate is unconditional; all-negative correctness uses the stated RH input.','Only RHζ_Q and primitive quadratic Dirichlet RH, a subfamily of adopted A_D. Classical CS Prop19 class-number bound, equation2.2/Cor14/Prop16 algebraic isogeny criterion, deterministic modular-polynomial construction, NT-C03 and the E16 different bound. No M, ring-class Hecke RH, Artin holomorphy, or elliptic GL2 RH.','complete bounded-certificate/input-reduction formulation proved here; whole author and root proof readings passed; no literature-priority claim','cm_recognition_dirichlet.tex/section.tex NT-E17. Full elementary discriminant bound2^17(h+1)^6, degree4 avoidance field Q(sqrtD,sqrt(rad6D)), exact split-prime cutoff, and determinant/evaluation/interpolation/division bit proof. CS arXivv4 Prop19pp9–10, eq2.2/Cor14p8, Prop16p9; direct Phi construction BCRS §2pp4–7/(9). Published faster CS Thm27 bound remains credited only to its own algorithm.','GRH_NIGHT/number_theory; cyclic-isogeny correspondences detect the quadratic H1 endomorphism algebra; a finite biquadratic Frobenius cover supplies a bounded correspondence degree. SGA1 ExposeV§7 finite-etale dictionary. The algorithm neither constructs class polynomials numerically nor outputs the CM order discriminant.')
add('NT-E18','For an elliptic curve over a varying number field F=Q[t]/(f), with monic irreducible f and Weierstrass coefficients supplied as dense binary rational coefficient lists/power-basis vectors, geometric CM can be decided deterministically in polynomial total input length under quadratic Dirichlet RH.','The exact A_quad subfamily and classical premises of NT-E17. The field and nonsingularity are input promises. Elementary rational field arithmetic/minimal-polynomial linear algebra; integrality of CM j-invariants. No maximal-order, conductor, integer-factorization or endomorphism oracle.','complete input-model translation proved here; whole author and root proof readings passed','cm_recognition_dirichlet.tex/section.tex NT-E18. Compute j, the first dependence among1,j,...,j^n, and its monic minimal polynomial. Explicit multiplication-matrix and determinant bounds keep all coefficient sizes polynomial. Reject nonintegral minimal polynomial; otherwise invoke E17. Dense encoding ensures n is bounded by input length.','GRH_NIGHT/number_theory; geometric CM of the H1 motive, invariant under twists and base extension, distinguished from F-isogeny in E16. Output is the distinction End_overlineF(E)=Z versus a quadratic order, not its discriminant or explicit endomorphisms. CS Algorithm2 near-quasilinear expected runtime retains extra Theorem35 heuristics.')

